    #[test]
    fn mega_cannot_evolve_twice_per_side() {
        // Doubles: both actives hold a matching stone and both declare
        // MegaEvolve the same turn. Only the first (slot 0) transforms —
        // the side's single mega permit is spent.
        let p1_json = r#"[
            {"species":"charizard","level":50,"ability":"blaze","item":"charizarditex","nature":"adamant","moves":["flareblitz","dragonclaw","earthquake","roost"],"evs":{"atk":252,"spe":252,"hp":4}},
            {"species":"kangaskhan","level":50,"ability":"scrappy","item":"kangaskhanite","nature":"adamant","moves":["doubleedge","suckerpunch","poweruppunch","fakeout"],"evs":{"atk":252,"spe":252,"hp":4}}
        ]"#;
        let p2_json = r#"[
            {"species":"snorlax","level":50,"ability":"thickfat","item":"","nature":"careful","moves":["bodyslam","rest","crunch","earthquake"],"evs":{"hp":252}},
            {"species":"blissey","level":50,"ability":"naturalcure","item":"","nature":"calm","moves":["seismictoss","softboiled","thunderwave","toxic"],"evs":{"hp":252}}
        ]"#;
        let p1 = TeamBuilder::from_json(p1_json).unwrap();
        let p2 = TeamBuilder::from_json(p2_json).unwrap();
        let mut b = Battle::new(BattleConfig { format: Format::Doubles, seed: 1 }, p1, p2);
        b.step(
            &[
                Choice::MegaEvolve { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P2, 0)) },
                Choice::MegaEvolve { actor_slot: 1, move_slot: 0, target: Some(t(SideRef::P2, 1)) },
            ],
            &[Choice::Pass { actor_slot: 0 }, Choice::Pass { actor_slot: 1 }],
        );
        assert_eq!(b.p1.team[0].species_id, data::species_id::CHARIZARDMEGAX, "slot 0 mega'd");
        assert_eq!(b.p1.team[1].species_id, data::species_id::KANGASKHAN, "slot 1 stayed base — permit spent");
        assert!(b.p1.conditions.mega_used);
    }

    #[test]
    fn mega_persists_through_switch_out_and_in() {
        // Mega Manectric switches out and back; it keeps the Mega forme
        // and the Mega ability (Intimidate), which re-fires on the return
        // switch-in (drops the foe's Attack again).
        let p1_json = r#"[
            {"species":"manectric","level":50,"ability":"lightningrod","item":"manectite","nature":"timid","moves":["thunderbolt","flamethrower","voltswitch","protect"],"evs":{"spa":252,"spe":252,"hp":4}},
            {"species":"snorlax","level":50,"ability":"thickfat","item":"","nature":"careful","moves":["bodyslam","rest","crunch","earthquake"],"evs":{"hp":252}}
        ]"#;
        let p2_json = r#"[
            {"species":"garchomp","level":50,"ability":"roughskin","item":"","nature":"jolly","moves":["dragonclaw","earthquake","protect","ironhead"],"evs":{"atk":252,"spe":252,"hp":4}}
        ]"#;
        let p1 = TeamBuilder::from_json(p1_json).unwrap();
        let p2 = TeamBuilder::from_json(p2_json).unwrap();
        let mut b = Battle::new(BattleConfig { format: Format::Singles, seed: 1 }, p1, p2);
        // Turn 1: mega (Intimidate fires once, foe Atk -1).
        b.step(
            &[Choice::MegaEvolve { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P2, 0)) }],
            &[Choice::Pass { actor_slot: 0 }],
        );
        assert_eq!(b.p1.team[0].species_id, data::species_id::MANECTRICMEGA);
        assert_eq!(b.p1.team[0].ability_id, data::ability_id::INTIMIDATE);
        assert_eq!(b.p2.team[0].boosts[0], -1, "Intimidate dropped foe Atk on mega");
        // Turn 2: switch Manectric out for Snorlax.
        b.step(
            &[Choice::Switch { actor_slot: 0, team_index: 1 }],
            &[Choice::Pass { actor_slot: 0 }],
        );
        // Turn 3: switch Manectric back in.
        b.step(
            &[Choice::Switch { actor_slot: 0, team_index: 0 }],
            &[Choice::Pass { actor_slot: 0 }],
        );
        assert_eq!(b.p1.team[0].species_id, data::species_id::MANECTRICMEGA, "forme persists through switch");
        assert_eq!(b.p1.team[0].ability_id, data::ability_id::INTIMIDATE, "base ability persists through switch");
        assert_eq!(b.p1.team[0].effective_ability_id(), data::ability_id::INTIMIDATE);
        assert_eq!(b.p2.team[0].boosts[0], -2, "Intimidate re-fired on the return switch-in");
    }

    #[test]
    fn mega_speed_governs_this_turn_move_order() {
        // Manectric's Speed jumps (105 → 135 base) on mega. With the foe's
        // Speed set between the pre- and post-mega values, the foe outspeeds
        // base Manectric but is outsped once Manectric Mega-Evolves.
        let p1_json = r#"[
            {"species":"manectric","level":50,"ability":"lightningrod","item":"manectite","nature":"timid","moves":["thunderbolt","flamethrower","voltswitch","protect"],"evs":{"spa":252,"spe":252,"hp":4}}
        ]"#;
        let p2_json = r#"[
            {"species":"garchomp","level":50,"ability":"roughskin","item":"","nature":"jolly","moves":["dragonclaw","earthquake","protect","ironhead"],"evs":{"atk":252,"spe":252,"hp":4}}
        ]"#;
        let p1 = TeamBuilder::from_json(p1_json).unwrap();
        let p2 = TeamBuilder::from_json(p2_json).unwrap();
        let mut b = Battle::new(BattleConfig { format: Format::Singles, seed: 1 }, p1, p2);
        let base_spe = b.p1.team[0].stats.spe;
        // Pin the foe's Speed one point above base Manectric.
        b.p2.team[0].stats.spe = base_spe + 1;
        use crate::rng::Rng;
        let mut rng = Rng::new(0);
        let p1c = [Choice::MegaEvolve { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P2, 0)) }];
        let p2c = [Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P1, 0)) }];
        // Before transforming: foe is faster.
        let pre = crate::order::action_order(&b, &p1c, &p2c, &mut rng);
        assert_eq!(pre[0].side, SideRef::P2, "foe outspeeds base Manectric");
        // Apply the mega transform, then re-order: Manectric now first.
        b.try_mega_evolve(SideRef::P1, 0);
        assert!(b.p1.team[0].stats.spe > base_spe + 1, "mega Speed exceeds the foe");
        let post = crate::order::action_order(&b, &p1c, &p2c, &mut rng);
        assert_eq!(post[0].side, SideRef::P1, "mega Manectric outspeeds the foe");
    }

    #[test]
    fn legal_choices_emits_mega_and_tera_variants() {
        // A stone-holder with an unspent mega + tera permit gets BOTH a
        // MegaEvolve and a Terastallize variant alongside each plain Move.
        let p1_json = r#"[
            {"species":"charizard","level":50,"ability":"blaze","item":"charizarditex","nature":"adamant","moves":["flareblitz","dragonclaw","earthquake","roost"],"evs":{"atk":252,"spe":252,"hp":4},"teratype":"fire"}
        ]"#;
        let p2_json = r#"[
            {"species":"snorlax","level":50,"ability":"thickfat","item":"","nature":"careful","moves":["bodyslam","rest","crunch","earthquake"]}
        ]"#;
        let p1 = TeamBuilder::from_json(p1_json).unwrap();
        let p2 = TeamBuilder::from_json(p2_json).unwrap();
        let b = Battle::new(BattleConfig { format: Format::Singles, seed: 1 }, p1, p2);
        let lc = b.legal_choices(SideRef::P1, 0);
        assert!(lc.iter().any(|c| matches!(c, Choice::Move { .. })), "plain moves present");
        assert!(lc.iter().any(|c| matches!(c, Choice::Terastallize { .. })), "tera variants enumerated");
        assert!(lc.iter().any(|c| matches!(c, Choice::MegaEvolve { .. })), "mega variants enumerated");
        // A holder of a non-matching item gets Tera but no Mega.
        let p1b_json = r#"[
            {"species":"charizard","level":50,"ability":"blaze","item":"leftovers","nature":"adamant","moves":["flareblitz","dragonclaw","earthquake","roost"],"teratype":"fire"}
        ]"#;
        let p1b = TeamBuilder::from_json(p1b_json).unwrap();
        let p2b = TeamBuilder::from_json(p2_json).unwrap();
        let bb = Battle::new(BattleConfig { format: Format::Singles, seed: 1 }, p1b, p2b);
        let lcb = bb.legal_choices(SideRef::P1, 0);
        assert!(lcb.iter().any(|c| matches!(c, Choice::Terastallize { .. })), "tera still offered");
        assert!(!lcb.iter().any(|c| matches!(c, Choice::MegaEvolve { .. })), "no mega without matching stone");
    }

    #[test]
    fn zero_to_hero_transforms_palafin_on_switch_out() {
        // Palafin (Zero) becomes Palafin-Hero the moment it switches out,
        // gaining the Hero Attack (70 → 160 base). It does NOT transform at
        // battle start, and it stays Hero when switched back in.
        let p1_json = r#"[
            {"species":"palafin","level":50,"ability":"zerotohero","item":"choiceband","nature":"adamant","moves":["jetpunch","wavecrash","closecombat","flipturn"],"evs":{"atk":252,"spe":252,"hp":4}},
            {"species":"snorlax","level":50,"ability":"thickfat","item":"","nature":"careful","moves":["bodyslam","rest","crunch","earthquake"],"evs":{"hp":252}}
        ]"#;
        let p2_json = r#"[
            {"species":"garchomp","level":50,"ability":"roughskin","item":"","nature":"jolly","moves":["dragonclaw","earthquake","protect","ironhead"],"evs":{"atk":252,"spe":252,"hp":4}}
        ]"#;
        let p1 = TeamBuilder::from_json(p1_json).unwrap();
        let p2 = TeamBuilder::from_json(p2_json).unwrap();
        let mut b = Battle::new(BattleConfig { format: Format::Singles, seed: 1 }, p1, p2);
        // Battle start: still Zero form.
        assert_eq!(b.p1.team[0].species_id, data::species_id::PALAFIN, "Zero form at switch-in");
        let zero_atk = b.p1.team[0].stats.atk;
        // Switch Palafin out for Snorlax → transforms to Hero on the way out.
        b.step(
            &[Choice::Switch { actor_slot: 0, team_index: 1 }],
            &[Choice::Pass { actor_slot: 0 }],
        );
        assert_eq!(b.p1.team[0].species_id, data::species_id::PALAFINHERO, "Zero to Hero on switch-out");
        assert!(b.p1.team[0].stats.atk > zero_atk, "Hero Attack recomputed upward");
        // Switch Palafin-Hero back in — stays Hero.
        b.step(
            &[Choice::Switch { actor_slot: 0, team_index: 0 }],
            &[Choice::Pass { actor_slot: 0 }],
        );
        assert_eq!(b.p1.team[0].species_id, data::species_id::PALAFINHERO, "Hero forme persists");
    }

    #[test]
    fn stance_change_blade_on_attack_shield_on_kings_shield() {
        // Aegislash starts in Shield forme; an attacking move flips it to
        // Blade (Attack 50 → 140 base), King's Shield flips it back to
        // Shield, and leaving the field reverts Blade to Shield.
        let p1_json = r#"[
            {"species":"aegislash","level":50,"ability":"stancechange","item":"leftovers","nature":"quiet","moves":["shadowball","ironhead","kingsshield","shadowsneak"],"evs":{"spa":252,"hp":252,"def":4}},
            {"species":"snorlax","level":50,"ability":"thickfat","item":"","nature":"careful","moves":["bodyslam","rest","crunch","earthquake"],"evs":{"hp":252}}
        ]"#;
        let p2_json = r#"[
            {"species":"blissey","level":50,"ability":"naturalcure","item":"","nature":"calm","moves":["seismictoss","softboiled","thunderwave","toxic"],"evs":{"hp":252,"def":252}}
        ]"#;
        let p1 = TeamBuilder::from_json(p1_json).unwrap();
        let p2 = TeamBuilder::from_json(p2_json).unwrap();
        let mut b = Battle::new(BattleConfig { format: Format::Singles, seed: 1 }, p1, p2);
        assert_eq!(b.p1.team[0].species_id, data::species_id::AEGISLASH, "Shield forme at switch-in");
        let shield_atk = b.p1.team[0].stats.atk;
        // Attacking move (Iron Head, slot 1) → Blade forme.
        b.step(
            &[Choice::Move { actor_slot: 0, move_slot: 1, target: Some(t(SideRef::P2, 0)) }],
            &[Choice::Pass { actor_slot: 0 }],
        );
        assert_eq!(b.p1.team[0].species_id, data::species_id::AEGISLASHBLADE, "attack → Blade forme");
        assert!(b.p1.team[0].stats.atk > shield_atk, "Blade Attack recomputed upward");
        // King's Shield (slot 2) → back to Shield forme.
        b.step(
            &[Choice::Move { actor_slot: 0, move_slot: 2, target: None }],
            &[Choice::Pass { actor_slot: 0 }],
        );
        assert_eq!(b.p1.team[0].species_id, data::species_id::AEGISLASH, "King's Shield → Shield forme");
        assert_eq!(b.p1.team[0].stats.atk, shield_atk, "Shield Attack restored");
        // Attack again → Blade, then switch out → reverts to Shield.
        b.step(
            &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P2, 0)) }],
            &[Choice::Pass { actor_slot: 0 }],
        );
        assert_eq!(b.p1.team[0].species_id, data::species_id::AEGISLASHBLADE, "attack → Blade again");
        b.step(
            &[Choice::Switch { actor_slot: 0, team_index: 1 }],
            &[Choice::Pass { actor_slot: 0 }],
        );
        assert_eq!(b.p1.team[0].species_id, data::species_id::AEGISLASH, "Blade reverts to Shield on switch-out");
    }

    #[test]
    fn eviolite_reduces_damage_to_nfe() {
        // Pure damage-calc test: Chansey (NFE) holding Eviolite takes
        // 1/1.5 the special damage of no-item Chansey. We call into the
        // damage formula directly to bypass speed/move-order noise.
        use crate::damage::{calculate_damage, DamageContext};
        let p1_json = r#"[
            {"species":"chansey","level":50,"ability":"naturalcure","item":"eviolite","nature":"calm","moves":["softboiled","seismictoss","thunderwave","aromatherapy"],"evs":{"hp":252,"def":4,"spd":252}}
        ]"#;
        let p2_json = r#"[
            {"species":"miraidon","level":50,"ability":"hadronengine","item":"choicespecs","nature":"modest","moves":["thunderbolt","dracometeor","voltswitch","overheat"],"evs":{"spa":252,"spe":252,"hp":4}}
        ]"#;
        let p1 = TeamBuilder::from_json(p1_json).unwrap();
        let p2 = TeamBuilder::from_json(p2_json).unwrap();
        let mut chansey_evi = p1[0].clone();
        let miraidon = p2[0].clone();
        // No-item variant: same stats, blank item.
        let mut chansey_no = chansey_evi.clone();
        chansey_no.item_id = u16::MAX;
        // Apply Eviolite's spd bump to the eviolite variant (the battle
        // loop does this inline; we replicate it for the pure-fn call).
        chansey_evi.stats.spd = (chansey_evi.stats.spd as u32 * 3 / 2).min(u16::MAX as u32) as u16;

        let tbolt = data::MOVES.iter().position(|m| m.slug == "thunderbolt").unwrap() as u16;
        let ctx = DamageContext { roll: 15, ..DamageContext::default() };
        let dmg_evi = calculate_damage(&miraidon, &chansey_evi, tbolt, ctx);
        let dmg_no  = calculate_damage(&miraidon, &chansey_no,  tbolt, ctx);
        assert!(dmg_evi > 0 && dmg_no > 0);
        assert!(dmg_evi < dmg_no, "Eviolite should reduce damage to NFE: {dmg_evi} vs {dmg_no}");
        let ratio = (dmg_evi as u32) * 100 / dmg_no as u32;
        // Tight band around 67%.
        assert!(ratio >= 64 && ratio <= 72, "Eviolite ratio should be ~67%, got {ratio}%");
    }

    #[test]
    fn fake_out_flinches_first_turn() {
        // Singles to keep it tidy. Iron Hands knows Fake Out.
        let p1_json = r#"[
            {"species":"ironhands","level":50,"ability":"quarkdrive","item":"assaultvest","nature":"adamant","moves":["fakeout","drainpunch","thunderpunch","wildcharge"],"evs":{"atk":252,"hp":252,"def":4}}
        ]"#;
        let p2_json = r#"[
            {"species":"garchomp","level":50,"ability":"roughskin","item":"lifeorb","nature":"adamant","moves":["earthquake","dragonclaw","aerialace","ironhead"],"evs":{"atk":252,"spe":252,"hp":4}}
        ]"#;
        let p1 = TeamBuilder::from_json(p1_json).unwrap();
        let p2 = TeamBuilder::from_json(p2_json).unwrap();
        let mut b = Battle::new(BattleConfig { format: Format::Singles, seed: 7 }, p1, p2);
        let ih_hp = b.p1.team[0].current_hp;
        b.step(
            &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P2, 0)) }],
            &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P1, 0)) }],
        );
        // Fake Out priority +3 beats Earthquake. Target flinches → Earthquake skipped.
        // Fake Out is a contact move, so Garchomp's Rough Skin chips Iron Hands
        // for 1/8 max HP. Earthquake doesn't land (flinched), so the ONLY HP loss
        // is the Rough Skin recoil.
        let expected_recoil = (b.p1.team[0].stats.hp / 8).max(1);
        assert_eq!(
            b.p1.team[0].current_hp,
            ih_hp - expected_recoil,
            "Iron Hands took only Rough Skin recoil (no Earthquake damage — flinched)",
        );
        assert!(b.p2.team[0].current_hp < b.p2.team[0].stats.hp, "Garchomp took Fake Out damage");
    }

    #[test]
    fn damp_blocks_explosion_field_wide() {
        // PS data/abilities.ts:801 — Damp's onAnyTryMove cancels
        // Explosion / Self-Destruct / Mind Blown / Misty Explosion if any
        // active mon on the field has it. Foe with Damp ⇒ Explosion fails
        // (foe takes no damage). Control foe without Damp ⇒ Explosion
        // lands.
        let attacker = r#"[
            {"species":"snorlax","level":50,"ability":"thickfat","item":"","nature":"adamant","moves":["selfdestruct","bodyslam","crunch","earthquake"],"evs":{"atk":252,"hp":252}}
        ]"#;
        let damp_foe = r#"[
            {"species":"golduck","level":50,"ability":"damp","item":"","nature":"bold","moves":["surf","icebeam","calmmind","recover"],"evs":{"hp":252,"def":252}}
        ]"#;
        let plain_foe = r#"[
            {"species":"golduck","level":50,"ability":"cloudnine","item":"","nature":"bold","moves":["surf","icebeam","calmmind","recover"],"evs":{"hp":252,"def":252}}
        ]"#;

        // Returns true if the foe took damage from Self-Destruct.
        let foe_took_damage = |foe_json: &str| -> bool {
            let p1 = TeamBuilder::from_json(attacker).unwrap();
            let p2 = TeamBuilder::from_json(foe_json).unwrap();
            let mut b = Battle::new(
                BattleConfig { format: Format::Singles, seed: 5 },
                p1,
                p2,
            );
            let foe_hp_before = b.p2.team[0].current_hp;
            b.step(
                &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P2, 0)) }],
                &[Choice::Move { actor_slot: 0, move_slot: 3, target: Some(t(SideRef::P1, 0)) }],
            );
            b.p2.team[0].current_hp < foe_hp_before
        };

        assert!(
            !foe_took_damage(damp_foe),
            "Damp on the field must cancel Self-Destruct"
        );
        assert!(
            foe_took_damage(plain_foe),
            "control foe without Damp should take Self-Destruct damage"
        );
    }

    #[test]
    fn fake_out_fails_on_second_turn() {
        let p1_json = r#"[
            {"species":"ironhands","level":50,"ability":"quarkdrive","item":"assaultvest","nature":"adamant","moves":["fakeout","drainpunch","thunderpunch","wildcharge"],"evs":{"atk":252,"hp":252,"def":4}}
        ]"#;
        // Garchomp without Life Orb here so we don't mix Fake-Out testing
        // with attacker-item recoil bookkeeping.
        let p2_json = r#"[
            {"species":"garchomp","level":50,"ability":"roughskin","item":"leftovers","nature":"jolly","moves":["protect","dragonclaw","aerialace","ironhead"],"evs":{"atk":252,"spe":252,"hp":4}}
        ]"#;
        let p1 = TeamBuilder::from_json(p1_json).unwrap();
        let p2 = TeamBuilder::from_json(p2_json).unwrap();
        let mut b = Battle::new(BattleConfig { format: Format::Singles, seed: 7 }, p1, p2);
        // Turn 1: Iron Hands uses Drain Punch (anything non-Fake-Out), Garchomp Protects.
        b.step(
            &[Choice::Move { actor_slot: 0, move_slot: 1, target: Some(t(SideRef::P2, 0)) }],
            &[Choice::Move { actor_slot: 0, move_slot: 0, target: None }],
        );
        assert_eq!(b.p1.team[0].turns_active, 1, "Iron Hands has been out 1 turn");
        let chomp_hp = b.p2.team[0].current_hp;
        // Turn 2: Iron Hands tries Fake Out — should fail (no damage, no flinch).
        b.step(
            &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P2, 0)) }],
            &[Choice::Move { actor_slot: 0, move_slot: 1, target: Some(t(SideRef::P1, 0)) }],
        );
        // Garchomp may take leftovers heal then no other change, but that
        // tops out at max; either way no damage from Fake Out.
        assert!(b.p2.team[0].current_hp >= chomp_hp, "Fake Out failed → Garchomp didn't lose HP");
        // Garchomp's Dragon Claw should have hit Iron Hands.
        assert!(b.p1.team[0].current_hp < b.p1.team[0].stats.hp);
    }

    #[test]
    fn inner_focus_blocks_flinch() {
        // Fake Out is a 100%-flinch priority move. A slower Inner Focus
        // target must still get its move off; a control without Inner
        // Focus flinches and deals no damage. PS data/abilities.ts:2108.
        let attacker = r#"[
            {"species":"ironhands","level":50,"ability":"quarkdrive","item":"","nature":"adamant","moves":["fakeout","drainpunch","thunderpunch","wildcharge"],"evs":{"atk":252,"spe":252}}
        ]"#;
        // Target slower than Iron Hands so Fake Out lands first, then the
        // target tries to act. Crobat: fast naturally, so give it a Brave
        // nature + 0 Spe EVs is still fast — use Slowbro instead (slow).
        let inner = r#"[
            {"species":"slowbro","level":50,"ability":"innerfocus","item":"","nature":"relaxed","moves":["zenheadbutt","scald","slackoff","irondefense"],"evs":{"hp":252,"def":252}}
        ]"#;
        let control = r#"[
            {"species":"slowbro","level":50,"ability":"regenerator","item":"","nature":"relaxed","moves":["zenheadbutt","scald","slackoff","irondefense"],"evs":{"hp":252,"def":252}}
        ]"#;

        // Returns true if the target's move (Zen Headbutt → Iron Hands)
        // landed, i.e. it was NOT flinched by Fake Out.
        let target_moved = |target_json: &str| -> bool {
            let p1 = TeamBuilder::from_json(attacker).unwrap();
            let p2 = TeamBuilder::from_json(target_json).unwrap();
            let mut b = Battle::new(
                BattleConfig { format: Format::Singles, seed: 3 },
                p1,
                p2,
            );
            let ih_hp_before = b.p1.team[0].current_hp;
            b.step(
                &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P2, 0)) }],
                &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P1, 0)) }],
            );
            // If the target moved, Iron Hands took Zen Headbutt damage.
            b.p1.team[0].current_hp < ih_hp_before
        };

        assert!(
            target_moved(inner),
            "Inner Focus target should not flinch from Fake Out"
        );
        assert!(
            !target_moved(control),
            "control target without Inner Focus should flinch (no damage dealt)"
        );
    }

    #[test]
    fn zoom_lens_boosts_accuracy_when_holder_moves_after_target() {
        // PS data/items.ts:7820 — Zoom Lens ×1.2 accuracy if the holder
        // moves after its target (the target has no pending move action
        // left). A SLOW holder using a 70-acc move into a FAST target
        // (which already moved) should hit more often with Zoom Lens than
        // without. Count hits across many seeds.
        fn hits_with_item(item: &str) -> u32 {
            let mut hits = 0u32;
            for seed in 0u64..120 {
                let p1_json = format!(r#"[
                    {{"species":"snorlax","level":50,"ability":"thickfat","item":"{item}","nature":"sassy","moves":["focusblast","rest","sleeptalk","headbutt"],"evs":{{"hp":252,"spd":252}}}}
                ]"#);
                // Fast target that moves first each turn (status move so it
                // can't KO the holder), leaving Snorlax to swing afterward.
                let p2_json = r#"[
                    {"species":"regieleki","level":50,"ability":"transistor","item":"focussash","nature":"timid","moves":["thunderwave","rest","sleeptalk","protect"],"evs":{"spe":252}}
                ]"#;
                let p1 = TeamBuilder::from_json(&p1_json).unwrap();
                let p2 = TeamBuilder::from_json(p2_json).unwrap();
                let mut b = Battle::new(BattleConfig { format: Format::Singles, seed }, p1, p2);
                let hp_before = b.p2.team[0].current_hp;
                b.step(
                    &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P2, 0)) }],
                    &[Choice::Move { actor_slot: 0, move_slot: 1, target: Some(t(SideRef::P2, 0)) }],
                );
                // Regieleki rested (move_slot 1) targeting itself → no chip
                // on it except from a landed Focus Blast. HP drop = Snorlax
                // hit. (Rest only heals at full; Regieleki starts full so
                // Rest fails and leaves HP untouched.)
                if b.p2.team[0].current_hp < hp_before {
                    hits += 1;
                }
            }
            hits
        }
        let with_zoom = hits_with_item("zoomlens");
        let without = hits_with_item("");
        assert!(with_zoom > without,
            "Zoom Lens should land more 70-acc hits when moving last: zoom={with_zoom} none={without}");
    }

    #[test]
    fn switching_resets_turns_active() {
        // Doubles: switch out a mon and bring it back; turns_active should reset.
        let p1_json = r#"[
            {"species":"ironhands","level":50,"ability":"quarkdrive","item":"assaultvest","nature":"adamant","moves":["fakeout","drainpunch","thunderpunch","wildcharge"],"evs":{"atk":252,"hp":252,"def":4}},
            {"species":"garchomp","level":50,"ability":"roughskin","item":"lifeorb","nature":"jolly","moves":["earthquake","dragonclaw","aerialace","ironhead"],"evs":{"atk":252,"spe":252,"hp":4}},
            {"species":"pelipper","level":50,"ability":"drizzle","item":"focussash","nature":"modest","moves":["hurricane","weatherball","tailwind","airslash"]}
        ]"#;
        let p2_json = r#"[
            {"species":"pikachu","level":50,"ability":"static","item":"focussash","nature":"hasty","moves":["thunderbolt","quickattack","grassknot","feint"]},
            {"species":"fluttermane","level":50,"ability":"protosynthesis","item":"choicespecs","nature":"timid","moves":["moonblast","shadowball","dazzlinggleam","mysticalfire"]}
        ]"#;
        let p1 = TeamBuilder::from_json(p1_json).unwrap();
        let p2 = TeamBuilder::from_json(p2_json).unwrap();
        let mut b = Battle::new(BattleConfig { format: Format::Doubles, seed: 1 }, p1, p2);
        // Turn 1: pass everything to age the active mons.
        b.step(
            &[Choice::Pass { actor_slot: 0 }, Choice::Pass { actor_slot: 1 }],
            &[Choice::Pass { actor_slot: 0 }, Choice::Pass { actor_slot: 1 }],
        );
        assert_eq!(b.p1.team[0].turns_active, 1);
        // Turn 2: switch slot 0 (Iron Hands) → Pelipper.
        b.step(
            &[
                Choice::Switch { actor_slot: 0, team_index: 2 },
                Choice::Pass { actor_slot: 1 },
            ],
            &[Choice::Pass { actor_slot: 0 }, Choice::Pass { actor_slot: 1 }],
        );
        // Pelipper just switched in this turn; end-of-step increments → 1.
        assert_eq!(b.p1.team[2].turns_active, 1, "Pelipper has now been out 1 turn");
        // Turn 3: switch back to Iron Hands.
        b.step(
            &[
                Choice::Switch { actor_slot: 0, team_index: 0 },
                Choice::Pass { actor_slot: 1 },
            ],
            &[Choice::Pass { actor_slot: 0 }, Choice::Pass { actor_slot: 1 }],
        );
        // Iron Hands was reset on switch-in, then incremented at end → 1.
        // Its first action turn (turns_active == 0 during move resolution)
        // is the NEXT turn — confirm by trying Fake Out.
        assert_eq!(b.p1.team[0].turns_active, 1);
    }

    #[test]
    fn choice_band_locks_into_first_move() {
        let p1_json = r#"[
            {"species":"urshifu","level":50,"ability":"unseenfist","item":"choiceband","nature":"adamant","moves":["closecombat","wickedblow","aquajet","detect"],"evs":{"atk":252,"spe":252,"hp":4}}
        ]"#;
        let p2_json = r#"[
            {"species":"snorlax","level":50,"ability":"thickfat","item":"","nature":"careful","moves":["bodyslam","earthquake","crunch","rest"]}
        ]"#;
        let p1 = TeamBuilder::from_json(p1_json).unwrap();
        let p2 = TeamBuilder::from_json(p2_json).unwrap();
        let mut b = Battle::new(BattleConfig { format: Format::Singles, seed: 1 }, p1, p2);
        // First move: Wicked Blow (slot 1).
        b.step(
            &[Choice::Move { actor_slot: 0, move_slot: 1, target: Some(t(SideRef::P2, 0)) }],
            &[Choice::Pass { actor_slot: 0 }],
        );
        assert_eq!(b.p1.team[0].locked_move_slot(), 1);
        // legal_choices now only includes slot 1.
        let lc = b.legal_choices(SideRef::P1, 0);
        let moves_only: Vec<_> = lc.iter().filter(|c| matches!(c, Choice::Move { .. })).collect();
        for c in &moves_only {
            if let Choice::Move { move_slot, .. } = **c {
                assert_eq!(move_slot, 1, "Choice Band locks Urshifu into Wicked Blow");
            }
        }
        assert!(!moves_only.is_empty(), "should still have the locked move available");
    }

    #[test]
    fn gorilla_tactics_locks_into_first_move() {
        // Darmanitan-Galar @ Gorilla Tactics (no item). After using its
        // first move, legal_choices must only offer that slot — the
        // ability locks like a Choice item. The lock clears on switch
        // (covered by the shared locked_move_slot reset on switch-in).
        // PS data/abilities.ts:1609.
        let p1_json = r#"[
            {"species":"darmanitangalar","level":50,"ability":"gorillatactics","item":"","nature":"adamant","moves":["iciclecrash","flareblitz","uturn","earthquake"],"evs":{"atk":252,"spe":252,"hp":4}}
        ]"#;
        let p2_json = r#"[
            {"species":"snorlax","level":50,"ability":"thickfat","item":"","nature":"careful","moves":["bodyslam","earthquake","crunch","rest"]}
        ]"#;
        let p1 = TeamBuilder::from_json(p1_json).unwrap();
        let p2 = TeamBuilder::from_json(p2_json).unwrap();
        let mut b = Battle::new(BattleConfig { format: Format::Singles, seed: 1 }, p1, p2);
        // Before any move: all four slots selectable.
        let pre: Vec<_> = b.legal_choices(SideRef::P1, 0).into_iter()
            .filter(|c| matches!(c, Choice::Move { .. })).collect();
        assert!(pre.len() >= 2, "all moves selectable before first use");
        // First move: Earthquake (slot 3).
        b.step(
            &[Choice::Move { actor_slot: 0, move_slot: 3, target: Some(t(SideRef::P2, 0)) }],
            &[Choice::Pass { actor_slot: 0 }],
        );
        assert_eq!(b.p1.team[0].locked_move_slot(), 3, "Gorilla Tactics locks the slot");
        let lc = b.legal_choices(SideRef::P1, 0);
        let moves_only: Vec<_> = lc.iter().filter(|c| matches!(c, Choice::Move { .. })).collect();
        for c in &moves_only {
            if let Choice::Move { move_slot, .. } = **c {
                assert_eq!(move_slot, 3, "Gorilla Tactics locks Darmanitan into Earthquake");
            }
        }
        assert!(!moves_only.is_empty(), "locked move still available");
    }

