    #[test]
    fn protean_retypes_once_per_switch_in() {
        // PS data/abilities.ts:3452. Greninja (Protean) using a Water move
        // becomes mono-Water; a second move of a different type does NOT
        // re-type (gen-9 once-per-switch-in nerf). Water = 2, Dark = 15.
        let p1_json = r#"[
            {"species":"greninja","level":50,"ability":"protean","item":"focussash","nature":"timid","moves":["surf","darkpulse","icebeam","spikes"],"evs":{"spa":252,"spe":252,"hp":4}}
        ]"#;
        let p2_json = r#"[
            {"species":"snorlax","level":50,"ability":"thickfat","item":"leftovers","nature":"careful","moves":["bodyslam","earthquake","crunch","rest"],"evs":{"hp":252,"def":252,"spd":4}}
        ]"#;
        let p1 = TeamBuilder::from_json(p1_json).unwrap();
        let p2 = TeamBuilder::from_json(p2_json).unwrap();
        let mut b = Battle::new(BattleConfig { format: Format::Singles, seed: 9 }, p1, p2);
        // Turn 1: Surf → mono-Water.
        b.step(
            &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P2, 0)) }],
            &[Choice::Pass { actor_slot: 0 }],
        );
        let (types, n) = b.p1.team[0].effective_types();
        assert_eq!(n, 1, "Protean mono-types the holder");
        assert_eq!(types[0], 2, "Greninja becomes Water after Surf");
        // Turn 2: Dark Pulse — must NOT re-type (still Water).
        b.step(
            &[Choice::Move { actor_slot: 0, move_slot: 1, target: Some(t(SideRef::P2, 0)) }],
            &[Choice::Pass { actor_slot: 0 }],
        );
        let (types2, n2) = b.p1.team[0].effective_types();
        assert_eq!(n2, 1, "still mono-typed");
        assert_eq!(types2[0], 2, "Protean does not re-type a second time per switch-in");
    }

    #[test]
    fn libero_retypes_once_per_switch_in() {
        // PS data/abilities.ts:2273 — Libero is mechanically identical to
        // Protean and shares the once-per-switch-in latch. Cinderace
        // (Libero) using a Fire move becomes mono-Fire (code 1); a second
        // different-type move does not re-type.
        let p1_json = r#"[
            {"species":"cinderace","level":50,"ability":"libero","item":"focussash","nature":"jolly","moves":["pyroball","highjumpkick","suckerpunch","courtchange"],"evs":{"atk":252,"spe":252,"hp":4}}
        ]"#;
        let p2_json = r#"[
            {"species":"snorlax","level":50,"ability":"thickfat","item":"leftovers","nature":"careful","moves":["bodyslam","earthquake","crunch","rest"],"evs":{"hp":252,"def":252,"spd":4}}
        ]"#;
        let p1 = TeamBuilder::from_json(p1_json).unwrap();
        let p2 = TeamBuilder::from_json(p2_json).unwrap();
        let mut b = Battle::new(BattleConfig { format: Format::Singles, seed: 11 }, p1, p2);
        // Cinderace is natively Fire, so use a non-Fire move first (High
        // Jump Kick = Fighting) to actually change type and consume the
        // latch. Fighting = 6.
        b.step(
            &[Choice::Move { actor_slot: 0, move_slot: 1, target: Some(t(SideRef::P2, 0)) }],
            &[Choice::Pass { actor_slot: 0 }],
        );
        let (types, n) = b.p1.team[0].effective_types();
        assert_eq!(n, 1, "Libero mono-types the holder");
        assert_eq!(types[0], 6, "Cinderace becomes Fighting after High Jump Kick");
        // Second move (Fire Pyro Ball) must not re-type — latch spent.
        b.step(
            &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P2, 0)) }],
            &[Choice::Pass { actor_slot: 0 }],
        );
        let (types2, _) = b.p1.team[0].effective_types();
        assert_eq!(types2[0], 6, "Libero does not re-type a second time per switch-in");
    }

    #[test]
    fn toxic_debris_lays_toxic_spikes_on_physical_hit_only() {
        // PS data/abilities.ts:5061. Glimmora (Toxic Debris) hit by a
        // physical move lays one Toxic Spikes layer on the ATTACKER's side.
        // A special hit lays nothing.
        let p1_json = r#"[
            {"species":"glimmora","level":50,"ability":"toxicdebris","item":"leftovers","nature":"bold","moves":["powergem","sludgewave","spikyshield","stealthrock"],"evs":{"hp":252,"def":252,"spd":4}}
        ]"#;
        // P2 carries one physical and one special move.
        let p2_json = r#"[
            {"species":"garchomp","level":50,"ability":"roughskin","item":"lifeorb","nature":"adamant","moves":["earthquake","dragonpulse","stoneedge","ironhead"],"evs":{"atk":252,"spe":252,"hp":4}}
        ]"#;
        let p1 = TeamBuilder::from_json(p1_json).unwrap();
        let p2 = TeamBuilder::from_json(p2_json).unwrap();
        let mut b = Battle::new(BattleConfig { format: Format::Singles, seed: 5 }, p1, p2);
        // Special hit (Dragon Pulse, move_slot 1) — no Toxic Spikes laid.
        b.step(
            &[Choice::Pass { actor_slot: 0 }],
            &[Choice::Move { actor_slot: 0, move_slot: 1, target: Some(t(SideRef::P1, 0)) }],
        );
        assert_eq!(b.p2.conditions.toxic_spikes_layers, 0,
                   "special hit lays no Toxic Spikes");
        // Physical hit (Earthquake, move_slot 0) — one layer on P2's side.
        b.step(
            &[Choice::Pass { actor_slot: 0 }],
            &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P1, 0)) }],
        );
        assert_eq!(b.p2.conditions.toxic_spikes_layers, 1,
                   "physical hit lays one Toxic Spikes layer on the attacker side");
    }

    #[test]
    fn counter_returns_double_last_physical_damage_at_attacker() {
        // P1 Snorlax holds Counter (slot 0). P2 Garchomp uses a weak
        // physical move (Tackle) so the doubled retaliation can't KO and
        // mask the HP delta. Counter is priority -5, so Garchomp's hit
        // lands first and the recorded physical damage is available when
        // Counter resolves. Expect Garchomp to lose exactly 2× the HP
        // Snorlax lost. PS data/moves.ts:counter damageCallback.
        let p1_json = r#"[
            {"species":"snorlax","level":50,"ability":"thickfat","item":"","nature":"careful","moves":["counter","bodyslam","rest","crunch"],"evs":{"hp":252,"def":252,"spd":4}}
        ]"#;
        let p2_json = r#"[
            {"species":"garchomp","level":50,"ability":"sandveil","item":"","nature":"jolly","moves":["tackle","earthquake","dragonclaw","ironhead"],"evs":{"atk":252,"spe":252,"hp":4}}
        ]"#;
        let p1 = TeamBuilder::from_json(p1_json).unwrap();
        let p2 = TeamBuilder::from_json(p2_json).unwrap();
        let mut b = Battle::new(BattleConfig { format: Format::Singles, seed: 11 }, p1, p2);
        let snorlax_max = b.p1.team[0].current_hp;
        let chomp_max = b.p2.team[0].current_hp;
        b.step(
            &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P2, 0)) }],
            &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P1, 0)) }],
        );
        let snorlax_dmg = snorlax_max - b.p1.team[0].current_hp;
        let chomp_dmg = chomp_max - b.p2.team[0].current_hp;
        assert!(snorlax_dmg > 0, "Snorlax should have taken Tackle damage");
        assert_eq!(chomp_dmg, snorlax_dmg * 2, "Counter deals 2× the physical damage taken");
    }

