    #[test]
    fn after_you_lets_slow_ally_act_before_faster_foe() {
        // Doubles. P1 Whimsicott (fastest) After-Yous its slow ally Iron
        // Hands, which then KOs P2 Garchomp (HP set to 1) BEFORE Garchomp
        // — normally faster than Iron Hands — can fire Earthquake. So
        // Garchomp faints having dealt no damage and Whimsicott is untouched.
        // PS data/moves.ts:afteryou.
        let p1_json = r#"[
            {"species":"whimsicott","level":50,"ability":"infiltrator","item":"","nature":"jolly","moves":["afteryou","moonblast","tailwind","protect"],"evs":{"spe":252,"spa":252}},
            {"species":"ironhands","level":50,"ability":"quarkdrive","item":"","nature":"adamant","moves":["drainpunch","fakeout","wildcharge","thunderpunch"],"evs":{"atk":252,"hp":252}}
        ]"#;
        let p2_json = r#"[
            {"species":"garchomp","level":50,"ability":"sandveil","item":"","nature":"jolly","moves":["earthquake","dragonclaw","rockslide","protect"],"evs":{"atk":252,"spe":252}},
            {"species":"pelipper","level":50,"ability":"drizzle","item":"","nature":"modest","moves":["protect","surf","hurricane","tailwind"]}
        ]"#;

        // --- With After You: Iron Hands jumps ahead of Garchomp. ---
        let mut b = Battle::new(BattleConfig { format: Format::Doubles, seed: 7 },
            TeamBuilder::from_json(p1_json).unwrap(), TeamBuilder::from_json(p2_json).unwrap());
        b.p2.team[0].current_hp = 1; // Garchomp dies to any chip
        let whimsicott_max = b.p1.team[0].current_hp;
        b.step(
            &[
                Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P1, 1)) }, // After You → ally
                Choice::Move { actor_slot: 1, move_slot: 0, target: Some(t(SideRef::P2, 0)) }, // Drain Punch → Garchomp
            ],
            &[
                Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P1, 0)) }, // Garchomp Earthquake
                Choice::Move { actor_slot: 1, move_slot: 0, target: None },                   // Pelipper Protect
            ],
        );
        assert!(b.p2.team[0].fainted, "Iron Hands KO'd Garchomp");
        assert_eq!(b.p1.team[0].current_hp, whimsicott_max,
                   "After You: Garchomp fainted before its Earthquake — Whimsicott untouched");

        // --- Control (no After You): Whimsicott uses Moonblast instead, so
        //     Iron Hands stays slow and Garchomp's Earthquake lands first. ---
        let mut c = Battle::new(BattleConfig { format: Format::Doubles, seed: 7 },
            TeamBuilder::from_json(p1_json).unwrap(), TeamBuilder::from_json(p2_json).unwrap());
        c.p2.team[0].current_hp = 1;
        let whimsicott_max_c = c.p1.team[0].current_hp;
        c.step(
            &[
                Choice::Move { actor_slot: 0, move_slot: 1, target: Some(t(SideRef::P2, 1)) }, // Moonblast (not After You)
                Choice::Move { actor_slot: 1, move_slot: 0, target: Some(t(SideRef::P2, 0)) },
            ],
            &[
                Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P1, 0)) },
                Choice::Move { actor_slot: 1, move_slot: 0, target: None },
            ],
        );
        assert!(c.p1.team[0].current_hp < whimsicott_max_c,
                "Control: without After You, Garchomp's Earthquake hits Whimsicott");
    }

    #[test]
    fn quash_forces_target_to_act_last() {
        // Doubles. P1 Whimsicott (fastest) Quashes P2 Garchomp, which then
        // acts AFTER P1's slow Iron Hands — so Iron Hands KOs Garchomp
        // (HP 1) before it can fire Earthquake, and Whimsicott is untouched.
        // PS data/moves.ts:quash.
        let p1_json = r#"[
            {"species":"whimsicott","level":50,"ability":"infiltrator","item":"","nature":"jolly","moves":["quash","moonblast","tailwind","protect"],"evs":{"spe":252,"spa":252}},
            {"species":"ironhands","level":50,"ability":"quarkdrive","item":"","nature":"adamant","moves":["drainpunch","fakeout","wildcharge","thunderpunch"],"evs":{"atk":252,"hp":252}}
        ]"#;
        let p2_json = r#"[
            {"species":"garchomp","level":50,"ability":"sandveil","item":"","nature":"jolly","moves":["earthquake","dragonclaw","rockslide","protect"],"evs":{"atk":252,"spe":252}},
            {"species":"pelipper","level":50,"ability":"drizzle","item":"","nature":"modest","moves":["protect","surf","hurricane","tailwind"]}
        ]"#;

        let mut b = Battle::new(BattleConfig { format: Format::Doubles, seed: 7 },
            TeamBuilder::from_json(p1_json).unwrap(), TeamBuilder::from_json(p2_json).unwrap());
        b.p2.team[0].current_hp = 1;
        let whimsicott_max = b.p1.team[0].current_hp;
        b.step(
            &[
                Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P2, 0)) }, // Quash → Garchomp
                Choice::Move { actor_slot: 1, move_slot: 0, target: Some(t(SideRef::P2, 0)) }, // Drain Punch → Garchomp
            ],
            &[
                Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P1, 0)) }, // Garchomp Earthquake
                Choice::Move { actor_slot: 1, move_slot: 0, target: None },                   // Pelipper Protect
            ],
        );
        assert!(b.p2.team[0].fainted, "Iron Hands KO'd Garchomp");
        assert_eq!(b.p1.team[0].current_hp, whimsicott_max,
                   "Quash: Garchomp moved last and fainted before its Earthquake — Whimsicott untouched");

        // Control: Whimsicott uses Moonblast instead → no Quash → Garchomp
        // (faster than Iron Hands) lands Earthquake first.
        let mut c = Battle::new(BattleConfig { format: Format::Doubles, seed: 7 },
            TeamBuilder::from_json(p1_json).unwrap(), TeamBuilder::from_json(p2_json).unwrap());
        c.p2.team[0].current_hp = 1;
        let whimsicott_max_c = c.p1.team[0].current_hp;
        c.step(
            &[
                Choice::Move { actor_slot: 0, move_slot: 1, target: Some(t(SideRef::P2, 1)) },
                Choice::Move { actor_slot: 1, move_slot: 0, target: Some(t(SideRef::P2, 0)) },
            ],
            &[
                Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P1, 0)) },
                Choice::Move { actor_slot: 1, move_slot: 0, target: None },
            ],
        );
        assert!(c.p1.team[0].current_hp < whimsicott_max_c,
                "Control: without Quash, Garchomp's Earthquake hits Whimsicott");
    }

    #[test]
    fn rapid_spin_clears_own_hazards_and_traps_and_boosts_speed() {
        // PS data/moves.ts:rapidspin onAfterHit — clears the user's own
        // entry hazards + Leech Seed + partial-trap, then +1 Spe.
        let p1_json = r#"[
            {"species":"forretress","level":50,"ability":"sturdy","item":"","nature":"relaxed","moves":["rapidspin","gyroball","spikes","protect"],"evs":{"hp":252,"def":252,"spd":4}}
        ]"#;
        let p2_json = r#"[
            {"species":"blissey","level":50,"ability":"naturalcure","item":"","nature":"calm","moves":["seismictoss","softboiled","toxic","protect"],"evs":{"hp":252,"spd":252}}
        ]"#;
        let p1 = TeamBuilder::from_json(p1_json).unwrap();
        let p2 = TeamBuilder::from_json(p2_json).unwrap();
        let mut b = Battle::new(BattleConfig { format: Format::Singles, seed: 7 }, p1, p2);
        // Pile every modelled hazard onto P1's own side + a Leech Seed
        // and partial-trap volatile on the user.
        b.p1.conditions.spikes_layers = 3;
        b.p1.conditions.toxic_spikes_layers = 2;
        b.p1.conditions.stealth_rock = true;
        b.p1.conditions.sticky_web = true;
        b.p1.team[0].volatiles.add(crate::pokemon::Volatile {
            kind: crate::pokemon::VolatileKind::LeechSeed,
            turns_remaining: 0,
            payload: 0x0100,
        });
        b.p1.team[0].volatiles.add(crate::pokemon::Volatile {
            kind: crate::pokemon::VolatileKind::PartialTrap,
            turns_remaining: 0,
            payload: 5,
        });
        let spe_before = b.p1.team[0].boosts[4];
        b.step(
            &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P2, 0)) }],
            &[Choice::Pass { actor_slot: 0 }],
        );
        assert_eq!(b.p1.conditions.spikes_layers, 0, "Rapid Spin clears Spikes");
        assert_eq!(b.p1.conditions.toxic_spikes_layers, 0, "clears Toxic Spikes");
        assert!(!b.p1.conditions.stealth_rock, "clears Stealth Rock");
        assert!(!b.p1.conditions.sticky_web, "clears Sticky Web");
        assert!(!b.p1.team[0].volatiles.has(crate::pokemon::VolatileKind::LeechSeed),
                "frees user from Leech Seed");
        assert!(!b.p1.team[0].volatiles.has(crate::pokemon::VolatileKind::PartialTrap),
                "frees user from partial trap");
        assert_eq!(b.p1.team[0].boosts[4], spe_before + 1, "user gains +1 Spe");
    }

