    #[test]
    fn defog_clears_hazards_both_sides_screens_target_terrain_and_drops_evasion() {
        // PS data/moves.ts:defog onHit — hazards off BOTH sides, screens
        // off the TARGET's side, Terrain cleared, target evasion -1.
        let p1_json = r#"[
            {"species":"corviknight","level":50,"ability":"pressure","item":"","nature":"impish","moves":["defog","bravebird","roost","uturn"],"evs":{"hp":252,"def":252,"spd":4}}
        ]"#;
        let p2_json = r#"[
            {"species":"blissey","level":50,"ability":"naturalcure","item":"","nature":"calm","moves":["seismictoss","softboiled","reflect","protect"],"evs":{"hp":252,"spd":252}}
        ]"#;
        let p1 = TeamBuilder::from_json(p1_json).unwrap();
        let p2 = TeamBuilder::from_json(p2_json).unwrap();
        let mut b = Battle::new(BattleConfig { format: Format::Singles, seed: 7 }, p1, p2);
        // Hazards on BOTH sides; screens + a terrain on P2 (the target).
        b.p1.conditions.stealth_rock = true;
        b.p1.conditions.spikes_layers = 2;
        b.p2.conditions.toxic_spikes_layers = 2;
        b.p2.conditions.sticky_web = true;
        b.p2.conditions.reflect_turns = 5;
        b.p2.conditions.light_screen_turns = 5;
        b.p2.conditions.aurora_veil_turns = 5;
        b.terrain = crate::terrain::Terrain::Electric;
        b.terrain_turns = 5;
        let eva_before = b.p2.team[0].boosts[6];
        b.step(
            &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P2, 0)) }],
            &[Choice::Pass { actor_slot: 0 }],
        );
        // Hazards cleared on both sides.
        assert!(!b.p1.conditions.stealth_rock && b.p1.conditions.spikes_layers == 0,
                "Defog clears the user's own hazards");
        assert!(b.p2.conditions.toxic_spikes_layers == 0 && !b.p2.conditions.sticky_web,
                "Defog clears the target's hazards");
        // Screens cleared on the target's side.
        assert_eq!(b.p2.conditions.reflect_turns, 0, "clears target Reflect");
        assert_eq!(b.p2.conditions.light_screen_turns, 0, "clears target Light Screen");
        assert_eq!(b.p2.conditions.aurora_veil_turns, 0, "clears target Aurora Veil");
        // Terrain cleared.
        assert_eq!(b.terrain, crate::terrain::Terrain::None, "Defog clears Terrain");
        // Evasion dropped on the target.
        assert_eq!(b.p2.team[0].boosts[6], eva_before - 1, "target evasion -1");
    }

    #[test]
    fn defog_leaves_user_side_screens_intact() {
        // Control: Defog removes screens only from the TARGET's side, not
        // the user's own. Reflect on the Defogger's side survives.
        let p1_json = r#"[
            {"species":"corviknight","level":50,"ability":"pressure","item":"","nature":"impish","moves":["defog","bravebird","roost","uturn"],"evs":{"hp":252,"def":252,"spd":4}}
        ]"#;
        let p2_json = r#"[
            {"species":"blissey","level":50,"ability":"naturalcure","item":"","nature":"calm","moves":["seismictoss","softboiled","reflect","protect"],"evs":{"hp":252,"spd":252}}
        ]"#;
        let p1 = TeamBuilder::from_json(p1_json).unwrap();
        let p2 = TeamBuilder::from_json(p2_json).unwrap();
        let mut b = Battle::new(BattleConfig { format: Format::Singles, seed: 7 }, p1, p2);
        b.p1.conditions.reflect_turns = 5;
        b.step(
            &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P2, 0)) }],
            &[Choice::Pass { actor_slot: 0 }],
        );
        // 5 -> 4 from the normal end-of-step screen tick; Defog itself
        // does NOT clear the user's own screens (only the target's).
        assert_eq!(b.p1.conditions.reflect_turns, 4, "Defog leaves the user's own screens up");
    }

    #[test]
    fn tidy_up_clears_hazards_both_sides_and_subs_then_boosts() {
        // PS data/moves.ts:tidyup onHit — hazards off BOTH sides, every
        // Substitute removed, user gains Atk +1 and Spe +1.
        let p1_json = r#"[
            {"species":"grimmsnarl","level":50,"ability":"prankster","item":"","nature":"jolly","moves":["tidyup","substitute","spiritbreak","thunderwave"],"evs":{"hp":252,"spe":252}}
        ]"#;
        let p2_json = r#"[
            {"species":"blissey","level":50,"ability":"naturalcure","item":"","nature":"calm","moves":["seismictoss","softboiled","substitute","protect"],"evs":{"hp":252,"spd":252}}
        ]"#;
        let p1 = TeamBuilder::from_json(p1_json).unwrap();
        let p2 = TeamBuilder::from_json(p2_json).unwrap();
        let mut b = Battle::new(BattleConfig { format: Format::Singles, seed: 7 }, p1, p2);
        // Hazards on BOTH sides; a Substitute on each active mon.
        b.p1.conditions.stealth_rock = true;
        b.p1.conditions.spikes_layers = 1;
        b.p2.conditions.toxic_spikes_layers = 1;
        b.p2.conditions.sticky_web = true;
        b.p1.team[0].set_substitute_hp(50);
        b.p2.team[0].set_substitute_hp(60);
        let atk_before = b.p1.team[0].boosts[0];
        let spe_before = b.p1.team[0].boosts[4];
        b.step(
            &[Choice::Move { actor_slot: 0, move_slot: 0, target: None }],
            &[Choice::Pass { actor_slot: 0 }],
        );
        assert!(!b.p1.conditions.stealth_rock && b.p1.conditions.spikes_layers == 0,
                "Tidy Up clears the user's own hazards");
        assert!(b.p2.conditions.toxic_spikes_layers == 0 && !b.p2.conditions.sticky_web,
                "Tidy Up clears the foe's hazards");
        assert_eq!(b.p1.team[0].substitute_hp(), 0, "Tidy Up removes the user's Substitute");
        assert_eq!(b.p2.team[0].substitute_hp(), 0, "Tidy Up removes the foe's Substitute");
        assert_eq!(b.p1.team[0].boosts[0], atk_before + 1, "user gains +1 Atk");
        assert_eq!(b.p1.team[0].boosts[4], spe_before + 1, "user gains +1 Spe");
    }

    #[test]
    fn mortal_spin_clears_own_hazards_and_poisons_foe_but_no_speed_boost() {
        // PS data/moves.ts:mortalspin — clears the user's own hazards +
        // Leech Seed + partial-trap, poisons the foe (100% secondary), and
        // does NOT boost Speed (that's Rapid Spin only).
        let p1_json = r#"[
            {"species":"glimmora","level":50,"ability":"toxicdebris","item":"","nature":"timid","moves":["mortalspin","powergem","stealthrock","spikyshield"],"evs":{"spa":252,"spe":252}}
        ]"#;
        let p2_json = r#"[
            {"species":"garchomp","level":50,"ability":"roughskin","item":"","nature":"jolly","moves":["earthquake","dragonclaw","swordsdance","protect"],"evs":{"atk":252,"spe":252}}
        ]"#;
        let p1 = TeamBuilder::from_json(p1_json).unwrap();
        let p2 = TeamBuilder::from_json(p2_json).unwrap();
        let mut b = Battle::new(BattleConfig { format: Format::Singles, seed: 7 }, p1, p2);
        b.p1.conditions.stealth_rock = true;
        b.p1.conditions.spikes_layers = 2;
        b.p1.conditions.sticky_web = true;
        b.p1.team[0].volatiles.add(crate::pokemon::Volatile {
            kind: crate::pokemon::VolatileKind::LeechSeed,
            turns_remaining: 0,
            payload: 0x0100,
        });
        let spe_before = b.p1.team[0].boosts[4];
        b.step(
            &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P2, 0)) }],
            &[Choice::Pass { actor_slot: 0 }],
        );
        assert!(!b.p1.conditions.stealth_rock && b.p1.conditions.spikes_layers == 0
                    && !b.p1.conditions.sticky_web,
                "Mortal Spin clears the user's own hazards");
        assert!(!b.p1.team[0].volatiles.has(crate::pokemon::VolatileKind::LeechSeed),
                "frees user from Leech Seed");
        assert_eq!(b.p1.team[0].boosts[4], spe_before, "Mortal Spin does NOT boost Speed");
        // Garchomp (Ground/Dragon, not Poison/Steel) is now poisoned by
        // the 100% secondary.
        assert_eq!(b.p2.team[0].status, Status::Poison, "Mortal Spin poisons the foe");
    }

    #[test]
    fn court_change_swaps_side_conditions_between_sides() {
        // PS data/moves.ts:courtchange onHitField — swap every swappable
        // side condition between the two sides.
        let p1_json = r#"[
            {"species":"cinderace","level":50,"ability":"libero","item":"","nature":"jolly","moves":["courtchange","pyroball","suckerpunch","protect"],"evs":{"atk":252,"spe":252}}
        ]"#;
        let p2_json = r#"[
            {"species":"blissey","level":50,"ability":"naturalcure","item":"","nature":"calm","moves":["seismictoss","softboiled","reflect","protect"],"evs":{"hp":252,"spd":252}}
        ]"#;
        let p1 = TeamBuilder::from_json(p1_json).unwrap();
        let p2 = TeamBuilder::from_json(p2_json).unwrap();
        let mut b = Battle::new(BattleConfig { format: Format::Singles, seed: 7 }, p1, p2);
        // P1 (the Court Change user): Stealth Rock + Tailwind + Reflect.
        b.p1.conditions.stealth_rock = true;
        b.p1.conditions.tailwind_turns = 4;
        b.p1.conditions.reflect_turns = 5;
        // P2 (the foe): Spikes(3) + Toxic Spikes(2) + Sticky Web + Light Screen.
        b.p2.conditions.spikes_layers = 3;
        b.p2.conditions.toxic_spikes_layers = 2;
        b.p2.conditions.sticky_web = true;
        b.p2.conditions.light_screen_turns = 5;
        // A NON-swappable marker that must stay on its original side.
        b.p1.conditions.tera_used = true;
        b.step(
            &[Choice::Move { actor_slot: 0, move_slot: 0, target: None }],
            &[Choice::Pass { actor_slot: 0 }],
        );
        // P1's old conditions are now on P2.
        assert!(b.p2.conditions.stealth_rock, "Stealth Rock moved to the foe");
        // 4 -> 3 from the end-of-step Tailwind tick after the swap.
        assert_eq!(b.p2.conditions.tailwind_turns, 3, "Tailwind moved to the foe (then ticked)");
        // P2's old conditions are now on P1 (account for end-of-step ticks:
        // hazards/Sticky Web don't tick; Reflect/Light Screen tick 5 -> 4).
        assert_eq!(b.p1.conditions.spikes_layers, 3, "Spikes moved to the user");
        assert_eq!(b.p1.conditions.toxic_spikes_layers, 2, "Toxic Spikes moved to the user");
        assert!(b.p1.conditions.sticky_web, "Sticky Web moved to the user");
        assert_eq!(b.p1.conditions.light_screen_turns, 4, "Light Screen moved to the user (then ticked)");
        assert_eq!(b.p2.conditions.reflect_turns, 4, "Reflect moved to the foe (then ticked)");
        // Old hazards/screens are gone from their original sides.
        assert!(!b.p1.conditions.stealth_rock, "user's old Stealth Rock left");
        assert_eq!(b.p1.conditions.tailwind_turns, 0, "user's old Tailwind left");
        assert_eq!(b.p2.conditions.spikes_layers, 0, "foe's old Spikes left");
        // Non-swappable marker stays put.
        assert!(b.p1.conditions.tera_used, "tera_used is not swapped");
        assert!(!b.p2.conditions.tera_used, "tera_used stays off the foe");
    }

    #[test]
    fn color_change_retypes_holder_to_move_type_on_hit() {
        // PS data/abilities.ts:553. Kecleon (Normal) hit by a Water move
        // becomes mono-Water. Type code: Water = 2.
        let p1_json = r#"[
            {"species":"kecleon","level":50,"ability":"colorchange","item":"leftovers","nature":"careful","moves":["knockoff","suckerpunch","protect","recover"],"evs":{"hp":252,"def":4,"spd":252}}
        ]"#;
        let p2_json = r#"[
            {"species":"pelipper","level":50,"ability":"drizzle","item":"focussash","nature":"modest","moves":["surf","hurricane","tailwind","airslash"]}
        ]"#;
        let p1 = TeamBuilder::from_json(p1_json).unwrap();
        let p2 = TeamBuilder::from_json(p2_json).unwrap();
        let mut b = Battle::new(BattleConfig { format: Format::Singles, seed: 3 }, p1, p2);
        // Pre-check: Kecleon starts Normal (code 0), not Water.
        let (pre_types, pre_n) = b.p1.team[0].effective_types();
        assert!(!(0..pre_n as usize).any(|i| pre_types[i] == 2), "Kecleon not Water pre-hit");
        b.step(
            &[Choice::Pass { actor_slot: 0 }],
            &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P1, 0)) }],
        );
        // Kecleon survives (Focus Sash-free but high bulk vs Surf) — assert
        // it retyped to mono-Water.
        if b.p1.team[0].is_alive() {
            let (types, n) = b.p1.team[0].effective_types();
            assert_eq!(n, 1, "Color Change mono-types the holder");
            assert_eq!(types[0], 2, "Kecleon becomes Water after a Water hit");
        } else {
            panic!("Kecleon should survive a single Surf to observe the retype");
        }
    }

    #[test]
    fn moody_boosts_one_stat_plus2_and_a_different_stat_minus1() {
        // PS data/abilities.ts:2656. End-of-turn: +2 to one random combat
        // stat, -1 to a different one (acc/eva excluded). Starting from all
        // zeroes both candidate lists are full, so exactly one +2 and one
        // -1 land on distinct stats.
        let p1_json = r#"[
            {"species":"octillery","level":50,"ability":"moody","item":"leftovers","nature":"modest","moves":["surf","icebeam","gunkshot","protect"]}
        ]"#;
        let p2_json = r#"[
            {"species":"pikachu","level":50,"ability":"static","item":"focussash","nature":"hardy","moves":["thunderbolt","quickattack","grassknot","feint"]}
        ]"#;
        let p1 = TeamBuilder::from_json(p1_json).unwrap();
        let p2 = TeamBuilder::from_json(p2_json).unwrap();
        let mut b = Battle::new(BattleConfig { format: Format::Singles, seed: 7 }, p1, p2);
        b.step(
            &[Choice::Pass { actor_slot: 0 }],
            &[Choice::Pass { actor_slot: 0 }],
        );
        let boosts = b.p1.team[0].boosts;
        let plus2 = (0..5).filter(|&i| boosts[i] == 2).count();
        let minus1 = (0..5).filter(|&i| boosts[i] == -1).count();
        let other = (0..5).filter(|&i| boosts[i] != 0 && boosts[i] != 2 && boosts[i] != -1).count();
        // Accuracy / evasion must never move.
        assert_eq!(boosts[5], 0, "Moody must not touch accuracy");
        assert_eq!(boosts[6], 0, "Moody must not touch evasion");
        assert_eq!(plus2, 1, "exactly one stat at +2 (boosts={boosts:?})");
        assert_eq!(minus1, 1, "exactly one stat at -1 (boosts={boosts:?})");
        assert_eq!(other, 0, "no other stat changes (boosts={boosts:?})");
    }

    #[test]
    fn pastel_veil_blocks_poison_on_self_and_ally_and_cures_on_switch_in() {
        // PS data/abilities.ts:3144. Galarian Weezing (Pastel Veil) keeps
        // itself AND its partner immune to psn/tox, and cures any existing
        // poison on switch-in.
        let p1_json = r#"[
            {"species":"weezinggalar","level":50,"ability":"pastelveil","item":"focussash","nature":"bold","moves":["sludgebomb","flamethrower","willowisp","protect"]},
            {"species":"snorlax","level":50,"ability":"thickfat","item":"leftovers","nature":"careful","moves":["bodyslam","earthquake","crunch","rest"]}
        ]"#;
        let p2_json = r#"[
            {"species":"pikachu","level":50,"ability":"static","item":"focussash","nature":"hardy","moves":["thunderbolt","quickattack","grassknot","feint"]},
            {"species":"fluttermane","level":50,"ability":"protosynthesis","item":"choicespecs","nature":"timid","moves":["moonblast","shadowball","dazzlinggleam","mysticalfire"]}
        ]"#;
        let p1 = TeamBuilder::from_json(p1_json).unwrap();
        let p2 = TeamBuilder::from_json(p2_json).unwrap();
        let mut b = Battle::new(BattleConfig { format: Format::Doubles, seed: 1 }, p1, p2);
        // Pre-poison the Snorlax partner (slot 1) BEFORE switch-in cure ran;
        // simulate a residual cure by re-running the switch-in hook directly.
        b.p1.team[1].status = crate::pokemon::Status::Poison;
        crate::ability::on_switch_in(&mut b, SideRef::P1, 0);
        assert!(matches!(b.p1.team[1].status, crate::pokemon::Status::None),
                "Pastel Veil cures an ally's poison on switch-in");
        // Holder itself is psn-immune.
        b.try_set_status(SideRef::P1, 0, crate::pokemon::Status::Poison);
        assert!(matches!(b.p1.team[0].status, crate::pokemon::Status::None),
                "Pastel Veil holder is poison-immune");
        // Ally aura: the partner can't be poisoned while the veil is up.
        b.try_set_status(SideRef::P1, 1, crate::pokemon::Status::Toxic);
        assert!(matches!(b.p1.team[1].status, crate::pokemon::Status::None),
                "Pastel Veil ally is poison-immune");
    }

