    #[test]
    fn aroma_veil_blocks_encore() {
        // An Aroma Veil holder cannot be Encored. Whimsicott Encores the
        // foe after it has used a move; Aromatisse's last move is locked-in
        // only if Encore lands — it must not.
        let p1_json = r#"[
            {"species":"whimsicott","level":50,"ability":"prankster","item":"","nature":"timid","moves":["encore","tailwind","moonblast","protect"],"evs":{"spa":252,"spe":252,"hp":4}}
        ]"#;
        let p2_json = r#"[
            {"species":"aromatisse","level":50,"ability":"aromaveil","item":"","nature":"careful","moves":["moonblast","calmmind","protect","wish"]}
        ]"#;
        let p1 = TeamBuilder::from_json(p1_json).unwrap();
        let p2 = TeamBuilder::from_json(p2_json).unwrap();
        let mut b = Battle::new(BattleConfig { format: Format::Singles, seed: 1 }, p1, p2);
        // Turn 1: Whimsicott passes, Aromatisse uses Moonblast (sets last).
        b.step(
            &[Choice::Move { actor_slot: 0, move_slot: 1, target: None }],
            &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P1, 0)) }],
        );
        // Turn 2: Whimsicott (faster) Encores. Aroma Veil must veto it.
        b.step(
            &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P2, 0)) }],
            &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P1, 0)) }],
        );
        assert_eq!(
            b.p2.team[0].encored_move_slot(), 255,
            "Aroma Veil holder cannot be Encored",
        );
    }

    #[test]
    fn aroma_veil_blocks_cursed_body_disable() {
        // Cursed Body Disable (an ability-sourced volatile) is also blocked
        // by Aroma Veil on the would-be-disabled attacker. Aromatisse hits a
        // Cursed Body Gengar; across many trials it must NEVER be Disabled.
        let aroma_attacker = r#"[
            {"species":"aromatisse","level":50,"ability":"aromaveil","item":"","nature":"modest","moves":["moonblast","calmmind","protect","wish"]}
        ]"#;
        let gengar = r#"[
            {"species":"gengar","level":50,"ability":"cursedbody","item":"","nature":"timid","moves":["shadowball","sludgebomb","focusblast","thunderbolt"]}
        ]"#;
        let p1 = TeamBuilder::from_json(aroma_attacker).unwrap();
        let p2 = TeamBuilder::from_json(gengar).unwrap();
        for seed in 0..100u64 {
            let mut b = Battle::new(
                BattleConfig { format: Format::Singles, seed },
                p1.clone(),
                p2.clone(),
            );
            // Aromatisse attacks Gengar; Gengar passes so the hit lands.
            b.step(
                &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P2, 0)) }],
                &[Choice::Pass { actor_slot: 0 }],
            );
            assert_eq!(
                b.p1.team[0].disabled_move_slot(), 255,
                "Aroma Veil attacker is never Disabled by Cursed Body (seed {seed})",
            );
        }
    }

    #[test]
    fn static_paralyzes_contact_attacker_with_30pct_chance() {
        // Pikachu has Static. A contact attacker should be paralyzed
        // roughly 30% of the time across trials. Use Mortal Spin? No,
        // use a clean contact move like Body Slam (Snorlax). Snorlax
        // is Normal so it's not Paralysis-immune.
        let p1_json = r#"[
            {"species":"pikachu","level":50,"ability":"static","item":"","nature":"hardy","moves":["thunderbolt","quickattack","grassknot","feint"]}
        ]"#;
        let p2_json = r#"[
            {"species":"snorlax","level":50,"ability":"thickfat","item":"","nature":"careful","moves":["bodyslam","rest","sleeptalk","crunch"]}
        ]"#;
        let p1 = TeamBuilder::from_json(p1_json).unwrap();
        let p2 = TeamBuilder::from_json(p2_json).unwrap();
        let trials = 200u32;
        let mut paras = 0u32;
        for seed in 0..trials {
            let mut b = Battle::new(BattleConfig { format: Format::Singles, seed: seed as u64 }, p1.clone(), p2.clone());
            b.step(
                &[Choice::Pass { actor_slot: 0 }],
                &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P1, 0)) }],
            );
            if matches!(b.p2.team[0].status, Status::Paralysis) {
                paras += 1;
            }
        }
        let rate = paras * 100 / trials;
        assert!(
            rate >= 15 && rate <= 45,
            "Static paralysis rate {rate}% (expected ≈30% over 200 trials)"
        );
    }

    #[test]
    fn paralysis_full_skip_fires_25pct() {
        // PS data/conditions.ts:par onBeforeMove — `randomChance(1, 4)`
        // = 25% chance to be fully paralyzed (skip the move entirely).
        // Run 400 trials with a pre-paralyzed Snorlax attacking a
        // Snorlax and count the skipped turns.
        let p1_json = r#"[
            {"species":"snorlax","level":50,"ability":"thickfat","item":"","nature":"adamant","moves":["bodyslam","rest","sleeptalk","crunch"]}
        ]"#;
        let p2_json = r#"[
            {"species":"snorlax","level":50,"ability":"thickfat","item":"","nature":"careful","moves":["bodyslam","rest","sleeptalk","crunch"]}
        ]"#;
        let p1 = TeamBuilder::from_json(p1_json).unwrap();
        let p2 = TeamBuilder::from_json(p2_json).unwrap();
        let trials = 400u32;
        let mut skips = 0u32;
        for seed in 0..trials {
            let mut b = Battle::new(
                BattleConfig { format: Format::Singles, seed: seed as u64 },
                p1.clone(),
                p2.clone(),
            );
            b.p1.team[0].status = Status::Paralysis;
            let hp_before = b.p2.team[0].current_hp;
            b.step(
                &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P2, 0)) }],
                &[Choice::Pass { actor_slot: 0 }],
            );
            // If full-skip fired, no damage landed; if the move went
            // through, Snorlax took some damage.
            if b.p2.team[0].current_hp == hp_before {
                skips += 1;
            }
        }
        let rate = skips * 100 / trials;
        assert!(
            rate >= 15 && rate <= 35,
            "Paralysis full-skip rate {rate}% (expected ≈25% over 400 trials)"
        );
    }

    #[test]
    fn attract_applies_on_opposite_gender_then_clears_when_source_leaves() {
        // Attract on an opposite-gender target sets the `attract`
        // volatile recording the source slot; when the source switches
        // out the infatuation lifts (PS data/moves.ts:706 onUpdate).
        let p1_json = r#"[
            {"species":"snorlax","level":50,"ability":"thickfat","item":"","nature":"adamant","moves":["attract","bodyslam","rest","crunch"]},
            {"species":"gyarados","level":50,"ability":"intimidate","item":"","nature":"jolly","moves":["waterfall","crunch","dragondance","taunt"]}
        ]"#;
        let p2_json = r#"[
            {"species":"snorlax","level":50,"ability":"thickfat","item":"","nature":"careful","moves":["bodyslam","rest","sleeptalk","crunch"]}
        ]"#;
        let p1 = TeamBuilder::from_json(p1_json).unwrap();
        let p2 = TeamBuilder::from_json(p2_json).unwrap();
        let mut b = Battle::new(BattleConfig { format: Format::Singles, seed: 7 }, p1, p2);
        // Pin genders: source (P1/0) Male, target (P2/0) Female.
        b.p1.team[0].gender = data::Gender::Male;
        b.p2.team[0].gender = data::Gender::Female;

        // Turn 1: P1 uses Attract on the foe.
        b.step(
            &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P2, 0)) }],
            &[Choice::Pass { actor_slot: 0 }],
        );
        assert!(b.p2.team[0].is_attracted(), "opposite-gender Attract applied");
        // Source recorded as P1 (side 0), team index 0.
        assert_eq!(b.p2.team[0].attract_source(), Some((0, 0)), "source slot tracked");

        // Turn 2: the Attract source switches out → infatuation lifts.
        b.step(
            &[Choice::Switch { actor_slot: 0, team_index: 1 }],
            &[Choice::Pass { actor_slot: 0 }],
        );
        assert!(
            !b.p2.team[0].is_attracted(),
            "Attract cleared once the source left the field",
        );
    }

    #[test]
    fn attract_fails_on_genderless_or_same_gender() {
        let p1_json = r#"[
            {"species":"snorlax","level":50,"ability":"thickfat","item":"","nature":"adamant","moves":["attract","bodyslam","rest","crunch"]}
        ]"#;
        let p2_json = r#"[
            {"species":"snorlax","level":50,"ability":"thickfat","item":"","nature":"careful","moves":["bodyslam","rest","sleeptalk","crunch"]}
        ]"#;
        let p1 = TeamBuilder::from_json(p1_json).unwrap();
        let p2 = TeamBuilder::from_json(p2_json).unwrap();

        // Same gender (M vs M) → fail.
        let mut b = Battle::new(BattleConfig { format: Format::Singles, seed: 1 }, p1.clone(), p2.clone());
        b.p1.team[0].gender = data::Gender::Male;
        b.p2.team[0].gender = data::Gender::Male;
        b.step(
            &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P2, 0)) }],
            &[Choice::Pass { actor_slot: 0 }],
        );
        assert!(!b.p2.team[0].is_attracted(), "same-gender Attract fails");

        // Genderless target → fail.
        let mut b = Battle::new(BattleConfig { format: Format::Singles, seed: 1 }, p1.clone(), p2.clone());
        b.p1.team[0].gender = data::Gender::Male;
        b.p2.team[0].gender = data::Gender::Genderless;
        b.step(
            &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P2, 0)) }],
            &[Choice::Pass { actor_slot: 0 }],
        );
        assert!(!b.p2.team[0].is_attracted(), "genderless target immune to Attract");

        // Genderless source → fail.
        let mut b = Battle::new(BattleConfig { format: Format::Singles, seed: 1 }, p1, p2);
        b.p1.team[0].gender = data::Gender::Genderless;
        b.p2.team[0].gender = data::Gender::Female;
        b.step(
            &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P2, 0)) }],
            &[Choice::Pass { actor_slot: 0 }],
        );
        assert!(!b.p2.team[0].is_attracted(), "genderless source cannot Attract");
    }

