    #[test]
    fn attract_immobilize_fires_about_half() {
        // PS data/moves.ts:706 attract onBeforeMove rolls randomChance(1,2)
        // — 50% chance to be "immobilized by love" and skip the move.
        // Directly infatuate the attacker (source = the foe, P2/0) and
        // count skipped attacks over many seeds.
        let p1_json = r#"[
            {"species":"snorlax","level":50,"ability":"thickfat","item":"","nature":"adamant","moves":["bodyslam","rest","sleeptalk","crunch"]}
        ]"#;
        let p2_json = r#"[
            {"species":"snorlax","level":50,"ability":"thickfat","item":"","nature":"careful","moves":["bodyslam","rest","sleeptalk","crunch"]}
        ]"#;
        let p1 = TeamBuilder::from_json(p1_json).unwrap();
        let p2 = TeamBuilder::from_json(p2_json).unwrap();
        let trials = 400u32;
        let mut skips = 0u32;
        for seed in 0..trials {
            let mut b = Battle::new(
                BattleConfig { format: Format::Singles, seed: seed as u64 },
                p1.clone(),
                p2.clone(),
            );
            // Source = P2 (side 1), team index 0 — present and alive.
            b.p1.team[0].set_attract(1, 0);
            let hp_before = b.p2.team[0].current_hp;
            b.step(
                &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P2, 0)) }],
                &[Choice::Pass { actor_slot: 0 }],
            );
            if b.p2.team[0].current_hp == hp_before {
                skips += 1;
            }
        }
        let rate = skips * 100 / trials;
        assert!(
            (35..=65).contains(&rate),
            "Attract immobilize rate {rate}% (expected ≈50% over 400 trials)"
        );
    }

    #[test]
    fn attract_clears_when_source_faints() {
        // When the source faints, the infatuation lifts (PS onUpdate).
        // Directly infatuate P1/0 with source P2/0, then KO P2/0.
        let p1_json = r#"[
            {"species":"snorlax","level":50,"ability":"thickfat","item":"","nature":"adamant","moves":["bodyslam","rest","sleeptalk","crunch"]}
        ]"#;
        let p2_json = r#"[
            {"species":"snorlax","level":50,"ability":"thickfat","item":"","nature":"careful","moves":["bodyslam","rest","sleeptalk","crunch"]},
            {"species":"gyarados","level":50,"ability":"intimidate","item":"","nature":"jolly","moves":["waterfall","crunch","dragondance","taunt"]}
        ]"#;
        let p1 = TeamBuilder::from_json(p1_json).unwrap();
        let p2 = TeamBuilder::from_json(p2_json).unwrap();
        let mut b = Battle::new(BattleConfig { format: Format::Singles, seed: 5 }, p1, p2);
        b.p1.team[0].set_attract(1, 0);
        assert!(b.p1.team[0].is_attracted());
        // Faint the source and force a replacement switch-in.
        b.p2.team[0].current_hp = 0;
        b.p2.team[0].fainted = true;
        b.step(
            &[Choice::Pass { actor_slot: 0 }],
            &[Choice::Switch { actor_slot: 0, team_index: 1 }],
        );
        assert!(
            !b.p1.team[0].is_attracted(),
            "Attract cleared after the source fainted/left",
        );
    }

    #[test]
    fn paralysis_skip_consumes_one_range4_oracle_event() {
        // Oracle-pinned: PS recorded `randomChance(1, 4)`; lib.rs:389
        // lowers `Chance(true,1,4)` -> RngEvent::Range(0) (skip) and
        // `Chance(false,1,4)` -> Range(1) (move). Both must fully
        // consume one Range event at the paralysis site.
        let p1_json = r#"[
            {"species":"snorlax","level":50,"ability":"thickfat","item":"","nature":"adamant","moves":["bodyslam","rest","sleeptalk","crunch"]}
        ]"#;
        let p2_json = r#"[
            {"species":"snorlax","level":50,"ability":"thickfat","item":"","nature":"careful","moves":["bodyslam","rest","sleeptalk","crunch"]}
        ]"#;
        let p1 = TeamBuilder::from_json(p1_json).unwrap();
        let p2 = TeamBuilder::from_json(p2_json).unwrap();

        // Oracle queue: a single Range(0) — paralysis fires, attacker
        // skips. OraclePartial so non-Range draws (Tiebreak, etc.)
        // fall through to Splitmix without polluting the queue.
        let rng = crate::rng::Rng::oracle_partial(
            vec![crate::rng::RngEvent::Range(0)],
            0,
        );
        let mut b = Battle::with_rng(
            BattleConfig { format: Format::Singles, seed: 0 },
            rng,
            p1.clone(),
            p2.clone(),
        );
        b.p1.team[0].status = Status::Paralysis;
        let hp_before = b.p2.team[0].current_hp;
        b.step(
            &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P2, 0)) }],
            &[Choice::Pass { actor_slot: 0 }],
        );
        assert_eq!(
            b.p2.team[0].current_hp, hp_before,
            "Range(0) at par site must cause a full-skip with no damage"
        );
        // Engine consumed exactly the one Range event we queued.
        let (consumed, total) = b.oracle_pops().unwrap();
        assert_eq!((consumed, total), (1, 1));
    }

    #[test]
    fn confusion_duration_roll_2_to_5_after_lockin() {
        // PS data/conditions.ts:174 confusion.onStart rolls
        // `random(2, 6)` -> 2/3/4/5 turns. Engine pre-rolls
        // `2 + rng.range(4)` at the lock-in-end site so the draw
        // count matches PS even when the lock ends mid-batch.
        let p1_json = r#"[
            {"species":"garchomp","level":50,"ability":"roughskin","item":"","nature":"adamant","moves":["outrage","earthquake","protect","ironhead"]}
        ]"#;
        let p2_json = r#"[
            {"species":"snorlax","level":50,"ability":"thickfat","item":"","nature":"careful","moves":["bodyslam","crunch","sleeptalk","earthquake"]}
        ]"#;
        let p1 = TeamBuilder::from_json(p1_json).unwrap();
        let p2 = TeamBuilder::from_json(p2_json).unwrap();
        // Sweep enough seeds to cover all 4 possible roll outcomes.
        let mut seen = std::collections::BTreeSet::new();
        for seed in 0..200u64 {
            let mut b = Battle::new(BattleConfig { format: Format::Singles, seed }, p1.clone(), p2.clone());
            let mut steps = 0;
            while !b.p1.team[0].volatiles.has(crate::pokemon::VolatileKind::Confusion) && steps < 6 {
                b.step(
                    &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P2, 0)) }],
                    &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P1, 0)) }],
                );
                steps += 1;
            }
            if let Some(v) = b.p1.team[0].volatiles.get(crate::pokemon::VolatileKind::Confusion) {
                let dur = v.payload;
                assert!(
                    (2..=5).contains(&dur),
                    "confusion duration {dur} outside PS [2,5]"
                );
                seen.insert(dur);
            }
        }
        // Across 200 seeds we should see every outcome at least once.
        assert!(seen.len() >= 3, "duration variety too low: {seen:?}");
    }

    #[test]
    fn own_tempo_blocks_lockin_self_confusion() {
        // PS data/abilities.ts:3099 owntempo `onTryAddVolatile` vetoes
        // confusion from any source — including the self-confusion a
        // lock-in move (Outrage) inflicts when its lock ends. A control
        // mon WITHOUT Own Tempo must still get confused.
        let with_ot = r#"[
            {"species":"slowbro","level":50,"ability":"owntempo","item":"","nature":"adamant","moves":["outrage","earthquake","protect","ironhead"]}
        ]"#;
        let without_ot = r#"[
            {"species":"garchomp","level":50,"ability":"roughskin","item":"","nature":"adamant","moves":["outrage","earthquake","protect","ironhead"]}
        ]"#;
        let p2_json = r#"[
            {"species":"snorlax","level":50,"ability":"thickfat","item":"","nature":"careful","moves":["bodyslam","crunch","sleeptalk","earthquake"]}
        ]"#;
        let p2 = TeamBuilder::from_json(p2_json).unwrap();

        // Returns true if the lock-in user EVER became confused across a
        // seed sweep (driving Outrage every turn until the lock resolves).
        let ever_confused = |team_json: &str| -> bool {
            let p1 = TeamBuilder::from_json(team_json).unwrap();
            for seed in 0..50u64 {
                let mut b = Battle::new(
                    BattleConfig { format: Format::Singles, seed },
                    p1.clone(),
                    p2.clone(),
                );
                for _ in 0..5 {
                    if !b.p1.team[0].is_alive() {
                        break;
                    }
                    b.step(
                        &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P2, 0)) }],
                        &[Choice::Move { actor_slot: 0, move_slot: 2, target: Some(t(SideRef::P2, 0)) }],
                    );
                    if b.p1.team[0]
                        .volatiles
                        .has(crate::pokemon::VolatileKind::Confusion)
                    {
                        return true;
                    }
                }
            }
            false
        };

        assert!(
            !ever_confused(with_ot),
            "Own Tempo must block lock-in self-confusion"
        );
        assert!(
            ever_confused(without_ot),
            "control mon without Own Tempo should get confused"
        );
    }

    #[test]
    fn confuse_secondary_lands_on_damaging_move() {
        // Dynamic Punch — PS data/moves.ts:4363 `secondary: { chance:
        // 100, volatileStatus: 'confusion' }`. A 100%-chance confuser
        // must always confuse a hit, non-immune target, with a duration
        // in PS's [2,5] range. Machamp's No Guard makes the 50%-accuracy
        // move connect every time.
        // Machamp slow (Brave 0 IV would be ideal; Bold suffices since
        // Zapdos outspeeds it regardless). No Guard is unmodelled so the
        // 50%-acc Dynamic Punch still misses some seeds — fine, we only
        // assert on the hits.
        let p1_json = r#"[
            {"species":"machamp","level":50,"ability":"noguard","item":"","nature":"bold","moves":["dynamicpunch","earthquake","protect","rockslide"]}
        ]"#;
        // Zapdos: Electric/Flying resists Fighting (0.5x) and base 100
        // speed outspeeds Machamp, so it ACTS FIRST — meaning its
        // confusion volatile is read post-step with the apply-time
        // duration intact (the confusion onBeforeMove decrement only
        // fires on the confused mon's OWN turn, which already passed
        // before it was confused this turn). It also comfortably
        // survives a resisted Dynamic Punch so the secondary applies.
        let p2_json = r#"[
            {"species":"zapdos","level":50,"ability":"static","item":"","nature":"bold","moves":["roost","thunderbolt","sleeptalk","drillpeck"]}
        ]"#;
        let p1 = TeamBuilder::from_json(p1_json).unwrap();
        let p2 = TeamBuilder::from_json(p2_json).unwrap();
        let mut seen = std::collections::BTreeSet::new();
        let mut hits = 0;
        for seed in 0..120u64 {
            let mut b = Battle::new(
                BattleConfig { format: Format::Singles, seed },
                p1.clone(),
                p2.clone(),
            );
            let hp_before = b.p2.team[0].current_hp;
            b.step(
                &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P2, 0)) }],
                &[Choice::Move { actor_slot: 0, move_slot: 2, target: Some(t(SideRef::P2, 0)) }],
            );
            // No Guard is unmodelled, so Dynamic Punch (50% acc) misses on
            // some seeds; only assert the 100% confuse on seeds where it
            // actually connected (target lost HP) AND survived — a KO'd
            // target is never confused (no `alive_post`), matching PS.
            if b.p2.team[0].current_hp >= hp_before || b.p2.team[0].fainted {
                continue;
            }
            hits += 1;
            let v = b.p2.team[0]
                .volatiles
                .get(crate::pokemon::VolatileKind::Confusion);
            assert!(
                v.is_some(),
                "Dynamic Punch (100% confuse) must confuse a target it hit (seed {seed})"
            );
            let dur = v.unwrap().payload;
            assert!((2..=5).contains(&dur), "confusion duration {dur} outside PS [2,5]");
            seen.insert(dur);
        }
        assert!(hits >= 5, "too few hits to validate ({hits})");
        assert!(seen.len() >= 2, "duration variety too low: {seen:?}");
    }

    #[test]
    fn no_guard_auto_hits_both_directions() {
        // No Guard — PS data/abilities.ts:2960. While a No Guard mon is on
        // the field, EVERY move involving it (as source OR target) skips the
        // accuracy roll and always hits. A 50%-accuracy move must connect on
        // EVERY seed in both directions; a non-No-Guard control must miss on
        // at least one seed (proving the move is genuinely inaccurate and the
        // ability — not luck — is what makes it never miss).
        // Bulbapedia: <https://bulbapedia.bulbagarden.net/wiki/No_Guard_(Ability)>.
        //
        // Machamp uses Dynamic Punch (50% acc, Fighting). Snorlax (Normal,
        // huge HP, slow) is the punching bag — it survives the hit so HP-loss
        // is a clean "did it connect" signal, and it is not immune to
        // Fighting. Snorlax answers with Body Slam aimed at Machamp
        // (move_slot 1) — a move that touches only Machamp's HP, never
        // Snorlax's, so it can't mask the signal we measure on Snorlax.
        let attacker_json = |ability: &str| {
            format!(
                r#"[{{"species":"machamp","level":50,"ability":"{ability}","item":"","nature":"adamant","moves":["dynamicpunch","earthquake","protect","rockslide"]}}]"#
            )
        };
        let target_json = |ability: &str| {
            format!(
                r#"[{{"species":"snorlax","level":50,"ability":"{ability}","item":"","nature":"sassy","moves":["dynamicpunch","bodyslam","protect","crunch"]}}]"#
            )
        };

        // --- Attacker side: Machamp(No Guard) Dynamic Punch ALWAYS hits. ---
        let p1 = TeamBuilder::from_json(&attacker_json("noguard")).unwrap();
        let p2 = TeamBuilder::from_json(&target_json("thickfat")).unwrap();
        for seed in 0..120u64 {
            let mut b = Battle::new(
                BattleConfig { format: Format::Singles, seed },
                p1.clone(),
                p2.clone(),
            );
            let hp_before = b.p2.team[0].current_hp;
            b.step(
                &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P2, 0)) }],
                &[Choice::Move { actor_slot: 0, move_slot: 1, target: Some(t(SideRef::P1, 0)) }],
            );
            assert!(
                b.p2.team[0].current_hp < hp_before,
                "No Guard attacker's 50%-acc move missed on seed {seed}"
            );
        }

        // --- Control: same Machamp WITHOUT No Guard misses on some seed. ---
        let p1c = TeamBuilder::from_json(&attacker_json("guts")).unwrap();
        let p2c = TeamBuilder::from_json(&target_json("thickfat")).unwrap();
        let mut control_missed = false;
        for seed in 0..120u64 {
            let mut b = Battle::new(
                BattleConfig { format: Format::Singles, seed },
                p1c.clone(),
                p2c.clone(),
            );
            let hp_before = b.p2.team[0].current_hp;
            b.step(
                &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P2, 0)) }],
                &[Choice::Move { actor_slot: 0, move_slot: 1, target: Some(t(SideRef::P1, 0)) }],
            );
            if b.p2.team[0].current_hp >= hp_before {
                control_missed = true;
                break;
            }
        }
        assert!(
            control_missed,
            "control (no No Guard) never missed — test isn't exercising accuracy"
        );

        // --- Defender side: a No Guard holder is ALWAYS hit by a 50%-acc move
        // aimed at it. Snorlax(No Guard) is targeted by Machamp(Guts) Dynamic
        // Punch; it must take damage on every seed. ---
        let p1d = TeamBuilder::from_json(&attacker_json("guts")).unwrap();
        let p2d = TeamBuilder::from_json(&target_json("noguard")).unwrap();
        for seed in 0..120u64 {
            let mut b = Battle::new(
                BattleConfig { format: Format::Singles, seed },
                p1d.clone(),
                p2d.clone(),
            );
            let hp_before = b.p2.team[0].current_hp;
            b.step(
                &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P2, 0)) }],
                &[Choice::Move { actor_slot: 0, move_slot: 1, target: Some(t(SideRef::P1, 0)) }],
            );
            assert!(
                b.p2.team[0].current_hp < hp_before,
                "move aimed at No Guard holder missed on seed {seed}"
            );
        }
    }

    #[test]
    fn confuse_secondary_blocked_by_own_tempo() {
        // Own Tempo — PS data/abilities.ts:3106 `onTryAddVolatile`
        // vetoes confusion from any source, including a damaging move's
        // confuse secondary. A 100% confuser (Dynamic Punch) must NOT
        // confuse an Own Tempo target. Lickilicky carries Own Tempo.
        let p1_json = r#"[
            {"species":"machamp","level":50,"ability":"noguard","item":"","nature":"adamant","moves":["dynamicpunch","earthquake","protect","rockslide"]}
        ]"#;
        let p2_json = r#"[
            {"species":"lickilicky","level":50,"ability":"owntempo","item":"","nature":"careful","moves":["bodyslam","crunch","sleeptalk","earthquake"]}
        ]"#;
        let p1 = TeamBuilder::from_json(p1_json).unwrap();
        let p2 = TeamBuilder::from_json(p2_json).unwrap();
        for seed in 0..20u64 {
            let mut b = Battle::new(
                BattleConfig { format: Format::Singles, seed },
                p1.clone(),
                p2.clone(),
            );
            b.step(
                &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P2, 0)) }],
                &[Choice::Move { actor_slot: 0, move_slot: 2, target: Some(t(SideRef::P2, 0)) }],
            );
            assert!(
                !b.p2.team[0]
                    .volatiles
                    .has(crate::pokemon::VolatileKind::Confusion),
                "Own Tempo must block confuse secondary (seed {seed})"
            );
        }
    }

    #[test]
    fn endure_survives_lethal_move_at_one_hp() {
        // PS data/moves.ts:4827 — the `endure` volatile's onDamage caps a
        // lethal MOVE hit at `target.hp - 1`. A frail mon (Caterpie) that
        // Endures a guaranteed-OHKO hit from a strong attacker must end
        // the turn alive at exactly 1 HP. Endure is priority 4, so it
        // resolves before the attacker's move every time.
        let attacker = r#"[
            {"species":"rayquaza","level":50,"ability":"airlock","item":"","nature":"adamant","moves":["dragonascent","extremespeed","earthquake","protect"]}
        ]"#;
        let endurer = r#"[
            {"species":"caterpie","level":5,"ability":"shielddust","item":"","nature":"hardy","moves":["endure","tackle","stringshot","bugbite"]}
        ]"#;
        let p1 = TeamBuilder::from_json(attacker).unwrap();
        let p2 = TeamBuilder::from_json(endurer).unwrap();
        for seed in 0..30u64 {
            let mut b = Battle::new(
                BattleConfig { format: Format::Singles, seed },
                p1.clone(),
                p2.clone(),
            );
            // P2 Endures (move 0), P1 attacks P2 with Extreme Speed (move 1).
            b.step(
                &[Choice::Move { actor_slot: 0, move_slot: 1, target: Some(t(SideRef::P2, 0)) }],
                &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P2, 0)) }],
            );
            assert!(
                b.p2.team[0].is_alive() && b.p2.team[0].current_hp == 1,
                "Endure must leave the target alive at 1 HP (seed {seed}, hp={})",
                b.p2.team[0].current_hp,
            );
        }
    }

    #[test]
    fn endure_expires_next_turn() {
        // Endure is a duration-1 volatile: it protects only the turn it
        // was used. Without re-using Endure, the next lethal hit KOs.
        let attacker = r#"[
            {"species":"rayquaza","level":50,"ability":"airlock","item":"","nature":"adamant","moves":["dragonascent","extremespeed","earthquake","protect"]}
        ]"#;
        let endurer = r#"[
            {"species":"caterpie","level":5,"ability":"shielddust","item":"","nature":"hardy","moves":["endure","tackle","stringshot","bugbite"]}
        ]"#;
        let p1 = TeamBuilder::from_json(attacker).unwrap();
        let p2 = TeamBuilder::from_json(endurer).unwrap();
        let mut b = Battle::new(
            BattleConfig { format: Format::Singles, seed: 0 },
            p1.clone(),
            p2.clone(),
        );
        // Turn 1: Endure + lethal hit → survive at 1.
        b.step(
            &[Choice::Move { actor_slot: 0, move_slot: 1, target: Some(t(SideRef::P2, 0)) }],
            &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P2, 0)) }],
        );
        assert_eq!(b.p2.team[0].current_hp, 1, "turn 1 endure should leave 1 HP");
        // The Endure volatile is duration-1; it is cleared at the START of
        // the next step's per-turn reset (same timing as the Protect flag),
        // so the functional check is that turn 2 — without re-using Endure —
        // no longer protects.
        // Turn 2: NO Endure (use Tackle), same lethal hit → faints.
        b.step(
            &[Choice::Move { actor_slot: 0, move_slot: 1, target: Some(t(SideRef::P2, 0)) }],
            &[Choice::Move { actor_slot: 0, move_slot: 1, target: Some(t(SideRef::P1, 0)) }],
        );
        assert!(
            b.p2.team[0].fainted,
            "without Endure the next lethal hit must KO",
        );
    }

    #[test]
    fn confusion_self_hit_consumes_percent_and_damage_roll() {
        // PS data/conditions.ts:180 — randomChance(33, 100) gate +
        // 40-BP typeless physical self-hit via getConfusionDamage.
        // Oracle-pinned: a PercentRoll(<= 33) at the gate triggers
        // the self-hit; the self-hit consumes one DamageRoll(_).
        let p1_json = r#"[
            {"species":"snorlax","level":50,"ability":"thickfat","item":"","nature":"adamant","moves":["bodyslam","rest","sleeptalk","crunch"]}
        ]"#;
        let p2_json = r#"[
            {"species":"snorlax","level":50,"ability":"thickfat","item":"","nature":"careful","moves":["bodyslam","rest","sleeptalk","crunch"]}
        ]"#;
        let p1 = TeamBuilder::from_json(p1_json).unwrap();
        let p2 = TeamBuilder::from_json(p2_json).unwrap();

        let rng = crate::rng::Rng::oracle_partial(
            vec![
                crate::rng::RngEvent::PercentRoll(1), // <= 33 → self-hit
                crate::rng::RngEvent::DamageRoll(0),  // max damage roll
            ],
            0,
        );
        let mut b = Battle::with_rng(
            BattleConfig { format: Format::Singles, seed: 0 },
            rng,
            p1.clone(),
            p2.clone(),
        );
        // Confuse the attacker with payload=4 (matches lock-in default).
        let m = b.p1.active_mon_mut(0).unwrap();
        let _ = m.volatiles.add(crate::pokemon::Volatile {
            kind: crate::pokemon::VolatileKind::Confusion,
            turns_remaining: 0,
            payload: 4,
        });
        let self_hp_before = b.p1.team[0].current_hp;
        let opp_hp_before = b.p2.team[0].current_hp;
        b.step(
            &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P2, 0)) }],
            &[Choice::Pass { actor_slot: 0 }],
        );
        assert!(
            b.p1.team[0].current_hp < self_hp_before,
            "confusion self-hit must reduce attacker HP"
        );
        assert_eq!(
            b.p2.team[0].current_hp, opp_hp_before,
            "opponent unscathed: the move never resolved"
        );
        // Engine consumed: 1 PercentRoll (gate) + 1 DamageRoll (self-dmg).
        let (consumed, _) = b.oracle_pops().unwrap();
        assert_eq!(consumed, 2, "expected 2 oracle pops (percent + damage)");
        // Confusion counter dropped to 3.
        let v = b.p1.team[0]
            .volatiles
            .get(crate::pokemon::VolatileKind::Confusion)
            .unwrap();
        assert_eq!(v.payload, 3);
    }

    #[test]
    fn confusion_gate_proceeds_on_high_percent() {
        // PercentRoll(34) > 33 → move proceeds normally, no self-hit.
        let p1_json = r#"[
            {"species":"snorlax","level":50,"ability":"thickfat","item":"","nature":"adamant","moves":["bodyslam","rest","sleeptalk","crunch"]}
        ]"#;
        let p2_json = r#"[
            {"species":"snorlax","level":50,"ability":"thickfat","item":"","nature":"careful","moves":["bodyslam","rest","sleeptalk","crunch"]}
        ]"#;
        let p1 = TeamBuilder::from_json(p1_json).unwrap();
        let p2 = TeamBuilder::from_json(p2_json).unwrap();
        let rng = crate::rng::Rng::oracle_partial(
            vec![crate::rng::RngEvent::PercentRoll(34)], // > 33 → proceed
            0,
        );
        let mut b = Battle::with_rng(
            BattleConfig { format: Format::Singles, seed: 0 },
            rng,
            p1.clone(),
            p2.clone(),
        );
        let m = b.p1.active_mon_mut(0).unwrap();
        let _ = m.volatiles.add(crate::pokemon::Volatile {
            kind: crate::pokemon::VolatileKind::Confusion,
            turns_remaining: 0,
            payload: 4,
        });
        let opp_hp_before = b.p2.team[0].current_hp;
        b.step(
            &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P2, 0)) }],
            &[Choice::Pass { actor_slot: 0 }],
        );
        assert!(
            b.p2.team[0].current_hp < opp_hp_before,
            "move proceeds: opponent took damage"
        );
    }

    #[test]
    fn confusion_counter_expires_and_removes_volatile() {
        // payload=1 → onBeforeMove decrements to 0 → volatile removed,
        // move proceeds. No RNG draws at the gate (early return).
        let p1_json = r#"[
            {"species":"snorlax","level":50,"ability":"thickfat","item":"","nature":"adamant","moves":["bodyslam","rest","sleeptalk","crunch"]}
        ]"#;
        let p2_json = r#"[
            {"species":"snorlax","level":50,"ability":"thickfat","item":"","nature":"careful","moves":["bodyslam","rest","sleeptalk","crunch"]}
        ]"#;
        let p1 = TeamBuilder::from_json(p1_json).unwrap();
        let p2 = TeamBuilder::from_json(p2_json).unwrap();
        let mut b = Battle::new(
            BattleConfig { format: Format::Singles, seed: 7 },
            p1,
            p2,
        );
        let m = b.p1.active_mon_mut(0).unwrap();
        let _ = m.volatiles.add(crate::pokemon::Volatile {
            kind: crate::pokemon::VolatileKind::Confusion,
            turns_remaining: 0,
            payload: 1,
        });
        b.step(
            &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P2, 0)) }],
            &[Choice::Pass { actor_slot: 0 }],
        );
        assert!(
            !b.p1.team[0]
                .volatiles
                .has(crate::pokemon::VolatileKind::Confusion),
            "Confusion volatile should be removed once counter hits 0"
        );
    }

    #[test]
    fn effect_spore_oracle_pinned_each_status_outcome() {
        // PS data/abilities.ts:effectspore — single `random(100)` on
        // contact hit. 0..10 → slp, 11..20 → par, 21..29 → psn, 30+ → none.
        // Engine maps via percent_1_100 (1..=100): 1..=11 → slp,
        // 12..=21 → par, 22..=30 → psn.
        let p1_json = r#"[
            {"species":"amoonguss","level":50,"ability":"effectspore","item":"","nature":"calm","moves":["spore","gigadrain","ragepowder","protect"]}
        ]"#;
        let p2_json = r#"[
            {"species":"snorlax","level":50,"ability":"thickfat","item":"","nature":"adamant","moves":["crunch","earthquake","sleeptalk","return"]}
        ]"#;
        let p1 = TeamBuilder::from_json(p1_json).unwrap();
        let p2 = TeamBuilder::from_json(p2_json).unwrap();
        // Crunch (contact) into Amoonguss. Two oracle PercentRolls:
        // the first for Crunch's 20% def-drop secondary (fail with
        // 100 so no def drop), the second for Effect Spore (5 → sleep).
        let rng = crate::rng::Rng::oracle_partial(
            vec![
                crate::rng::RngEvent::PercentRoll(100), // Crunch secondary: 100 > 20 → no def drop
                crate::rng::RngEvent::PercentRoll(5),   // Effect Spore: 5 ≤ 11 → sleep
            ],
            0,
        );
        let mut b = Battle::with_rng(
            BattleConfig { format: Format::Singles, seed: 0 },
            rng,
            p1.clone(),
            p2.clone(),
        );
        b.step(
            &[Choice::Pass { actor_slot: 0 }],
            &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P1, 0)) }],
        );
        assert!(
            matches!(b.p2.team[0].status, Status::Sleep),
            "PercentRoll 5 should sleep the contact attacker"
        );
    }

    #[test]
    fn effect_spore_no_op_on_grass_attacker() {
        // PS gates on `runStatusImmunity('powder')` — Grass-types
        // immune to all powder/spore effects.
        let p1_json = r#"[
            {"species":"amoonguss","level":50,"ability":"effectspore","item":"","nature":"calm","moves":["spore","gigadrain","ragepowder","protect"]}
        ]"#;
        let p2_json = r#"[
            {"species":"venusaur","level":50,"ability":"overgrow","item":"","nature":"adamant","moves":["bodyslam","gigadrain","sleeppowder","earthpower"]}
        ]"#;
        let p1 = TeamBuilder::from_json(p1_json).unwrap();
        let p2 = TeamBuilder::from_json(p2_json).unwrap();
        // Body Slam (contact) — Effect Spore should NOT fire on a Grass
        // attacker. Oracle queue gets no PercentRoll consumed at the
        // ability hook.
        let rng = crate::rng::Rng::oracle_partial(vec![], 0);
        let mut b = Battle::with_rng(
            BattleConfig { format: Format::Singles, seed: 0 },
            rng,
            p1.clone(),
            p2.clone(),
        );
        b.step(
            &[Choice::Pass { actor_slot: 0 }],
            &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P1, 0)) }],
        );
        assert!(
            matches!(b.p2.team[0].status, Status::None),
            "Grass attacker immune to Effect Spore"
        );
    }

    #[test]
