    #[test]
    fn disable_blocks_move_selection_and_use_then_clears() {
        // Plumbing test for the Disable volatile: a disabled slot is
        // filtered from legal_choices, a forced use of it does nothing
        // (no damage), the counter decrements each turn, and the lock
        // clears after its duration.
        let p1_json = r#"[
            {"species":"garchomp","level":50,"ability":"roughskin","nature":"jolly","moves":["earthquake","protect","dragonclaw","ironhead"]}
        ]"#;
        let p2_json = r#"[
            {"species":"corviknight","level":50,"ability":"pressure","nature":"impish","moves":["bravebird","roost","uturn","defog"],"evs":{"hp":252,"def":252,"spd":4}}
        ]"#;
        let p1 = TeamBuilder::from_json(p1_json).unwrap();
        let p2 = TeamBuilder::from_json(p2_json).unwrap();
        let mut b = Battle::new(BattleConfig { format: Format::Singles, seed: 1 }, p1, p2);

        // Disable Earthquake (slot 0) for 4 turns.
        b.p1.team[0].set_disable(4, 0);
        assert_eq!(b.p1.team[0].disable_turns(), 4);
        assert_eq!(b.p1.team[0].disabled_move_slot(), 0);

        // legal_choices must drop every Move on slot 0.
        let lc = b.legal_choices(SideRef::P1, 0);
        assert!(
            lc.iter().all(|c| !matches!(c, Choice::Move { move_slot: 0, .. })),
            "disabled slot 0 absent from legal_choices",
        );

        // Forcing the disabled move (slot 0) does no damage and does not
        // consume PP.
        let hp_before = b.p2.team[0].current_hp;
        let pp_before = b.p1.team[0].pp[0];
        b.step(
            &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P2, 0)) }],
            &[Choice::Pass { actor_slot: 0 }],
        );
        assert_eq!(b.p2.team[0].current_hp, hp_before, "disabled move dealt no damage");
        assert_eq!(b.p1.team[0].pp[0], pp_before, "disabled move spent no PP");
        // End-of-turn tick: 4 -> 3.
        assert_eq!(b.p1.team[0].disable_turns(), 3, "disable counted down once");

        // Spend the remaining duration using Protect (slot 1).
        for _ in 0..3 {
            b.step(
                &[Choice::Move { actor_slot: 0, move_slot: 1, target: None }],
                &[Choice::Pass { actor_slot: 0 }],
            );
        }
        assert_eq!(b.p1.team[0].disable_turns(), 0, "disable expired");
        assert!(!b.p1.team[0].volatiles.has(crate::pokemon::VolatileKind::Disable),
            "Disable volatile removed");
        // Slot 0 is selectable again.
        let lc = b.legal_choices(SideRef::P1, 0);
        assert!(
            lc.iter().any(|c| matches!(c, Choice::Move { move_slot: 0, .. })),
            "slot 0 selectable after Disable clears",
        );
    }

    #[test]
    fn throat_chop_locks_sound_moves_for_two_turns() {
        // Throat Chop (Dark physical) applies the 2-turn `throatchop`
        // lockout to the target as a 100% secondary on hit: the target's
        // sound moves (Hyper Voice here) vanish from legal_choices and
        // fail if forced, while non-sound moves stay selectable. The
        // lockout counts down each end of turn and clears on turn 3.
        // PS data/moves.ts:throatchop condition (duration 2).
        let p1_json = r#"[
            {"species":"weavile","level":50,"ability":"pressure","nature":"jolly","moves":["throatchop","iceshard","swordsdance","protect"],"evs":{"atk":252,"spe":252,"hp":4}}
        ]"#;
        // P2: Sylveon knows Hyper Voice (sound, slot 0) + Calm Mind
        // (non-sound, slot 1). Bulky so it survives the Throat Chop hits.
        let p2_json = r#"[
            {"species":"sylveon","level":50,"ability":"pixilate","nature":"calm","moves":["hypervoice","calmmind","wish","protect"],"evs":{"hp":252,"spd":252,"def":4}}
        ]"#;
        let p1 = TeamBuilder::from_json(p1_json).unwrap();
        let p2 = TeamBuilder::from_json(p2_json).unwrap();
        let mut b = Battle::new(BattleConfig { format: Format::Singles, seed: 1 }, p1, p2);

        // Before Throat Chop: Hyper Voice (sound, slot 0) is selectable.
        let lc0 = b.legal_choices(SideRef::P2, 0);
        assert!(
            lc0.iter().any(|c| matches!(c, Choice::Move { move_slot: 0, .. })),
            "sound move selectable before Throat Chop",
        );

        // P1 Throat Chops P2. The 100% secondary applies the lockout.
        b.step(
            &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P2, 0)) }],
            &[Choice::Move { actor_slot: 0, move_slot: 1, target: None }],
        );
        assert!(b.p2.team[0].is_alive(), "Sylveon survived Throat Chop");
        // Volatile set to 2, ticked once at end of turn -> 1.
        assert_eq!(b.p2.team[0].throat_chop_turns(), 1, "lockout applied (2), ticked to 1");

        // Turn 2: Hyper Voice (sound, slot 0) is filtered out, but the
        // non-sound Calm Mind (slot 1) remains selectable.
        let lc = b.legal_choices(SideRef::P2, 0);
        assert!(
            lc.iter().all(|c| !matches!(c, Choice::Move { move_slot: 0, .. })),
            "sound move absent from legal_choices while locked",
        );
        assert!(
            lc.iter().any(|c| matches!(c, Choice::Move { move_slot: 1, .. })),
            "non-sound move still selectable while locked",
        );

        // Forcing the sound move (slot 0) does nothing — no damage, no PP.
        let hp_before = b.p1.team[0].current_hp;
        let pp_before = b.p2.team[0].pp[0];
        b.step(
            &[Choice::Move { actor_slot: 0, move_slot: 1, target: None }],
            &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P1, 0)) }],
        );
        assert_eq!(b.p1.team[0].current_hp, hp_before, "locked sound move dealt no damage");
        assert_eq!(b.p2.team[0].pp[0], pp_before, "locked sound move spent no PP");

        // End of turn 2 tick: 1 -> 0, lockout clears.
        assert_eq!(b.p2.team[0].throat_chop_turns(), 0, "lockout expired after 2 turns");
        assert!(
            !b.p2.team[0].volatiles.has(crate::pokemon::VolatileKind::ThroatChop),
            "ThroatChop volatile removed",
        );

        // Turn 3: the sound move is selectable again.
        let lc = b.legal_choices(SideRef::P2, 0);
        assert!(
            lc.iter().any(|c| matches!(c, Choice::Move { move_slot: 0, .. })),
            "sound move selectable again after lockout clears",
        );
    }

    #[test]
    fn charge_volatile_clears_after_electric_move() {
        // The Charge volatile (set here directly, as Wind Power / the
        // Charge move will later) survives until the holder fires an
        // Electric move, then is removed.
        let p1_json = r#"[
            {"species":"zapdos","level":50,"ability":"static","nature":"modest","moves":["thunderbolt","roost","heatwave","uturn"],"evs":{"spa":252,"spe":252,"hp":4}}
        ]"#;
        let p2_json = r#"[
            {"species":"blissey","level":50,"ability":"naturalcure","nature":"calm","moves":["seismictoss","softboiled","toxic","protect"],"evs":{"hp":252,"spd":252,"def":4}}
        ]"#;
        let p1 = TeamBuilder::from_json(p1_json).unwrap();
        let p2 = TeamBuilder::from_json(p2_json).unwrap();
        let mut b = Battle::new(BattleConfig { format: Format::Singles, seed: 1 }, p1, p2);

        b.p1.team[0].set_charged(true);
        assert!(b.p1.team[0].is_charged(), "Charge applied");

        // Use Thunderbolt (Electric, slot 0): the ×2 lands and the
        // volatile is consumed.
        b.step(
            &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P2, 0)) }],
            &[Choice::Move { actor_slot: 0, move_slot: 3, target: None }],
        );
        assert!(!b.p1.team[0].is_charged(), "Charge consumed after Electric move");

        // Re-apply, then use a non-Electric move (Heat Wave, slot 2):
        // the volatile must persist.
        b.p1.team[0].set_charged(true);
        b.step(
            &[Choice::Move { actor_slot: 0, move_slot: 2, target: Some(t(SideRef::P2, 0)) }],
            &[Choice::Move { actor_slot: 0, move_slot: 3, target: None }],
        );
        assert!(b.p1.team[0].is_charged(), "Charge persists through a non-Electric move");
    }

